GimCorpus.put(132,0,[[1,1,"דִּבְרֵי נְחֶמְיָה וְגוֹ׳. מִכָּאן וָאֵילָךְ כָּתַב נְחֶמְיָה סֵפֶר זֶה:",1,0],[1,1,"שְׁנַת עֶשְׂרִים. הִיא שְׁנַת עֶשְׂרִים לְדָרְיָוֶשׁ הַמֶּלֶךְ שֶׁהוּא אַרְתַּחְשַׁשְׂתָּא. וּבְמַסֶּכֶת רֹאשׁ הַשָּׁנָה מָצָאנוּ: שְׁנַת עֶשְׂרִים ״שְׁנַת עֶשְׂרִים״ לִגְזֵרָה שָׁוָה, מִן הַכָּתוּב שֶׁנֶּאֱמַר לְמַטָּה ״וַיְהִי בְחֹדֶשׁ נִיסָן שְׁנַת עֶשְׂרִים לְאַרְתַּחְשַׁשְׂתָּא וְגוֹ׳״ (נחמיה ב:א). וּמֵחֹדֶשׁ תִּשְׁרֵי הָיוּ מוֹנִין לְחֶשְׁבּוֹן הַשָּׁנִים, וְעַל כֵּן נֶאֱמַר כָּאן: וַיְהִי בְחֹדֶשׁ כִּסְלֵו שְׁנַת עֶשְׂרִים וְגוֹ׳, וְהוּא כִּסְלֵו הַבָּא לְאַחַר תִּשְׁרֵי, וּלְמַטָּה נֶאֱמַר ״וַיְהִי בְחֹדֶשׁ נִיסָן שְׁנַת עֶשְׂרִים וְגוֹמֵר״, הוּא נִיסָן שֶׁבְּאוֹתָהּ שָׁנָה. וְאֵינִי יָכוֹל לִפְתֹּר וְלוֹמַר מִנִּיסָן הָיוּ מוֹנִין לְחֶשְׁבּוֹן שְׁנוֹתֵיהֶם, וְאוֹתוֹ מַעֲשֶׂה הַכָּתוּב לְמַטָּה שֶׁנֶּאֱמַר ״וַיְהִי בְחֹדֶשׁ נִיסָן וְגוֹ׳״ הָיָה קֹדֶם מַעֲשֶׂה זֶה שֶׁנֶּאֱמַר וַיְהִי בְחֹדֶשׁ כִּסְלֵו שְׁנַת עֶשְׂרִים וְגוֹ׳, וְאֵין מֻקְדָּם וּמְאֻחָר בָּהֶם, דָּבָר זֶה אֵינִי יָכוֹל לִפְתֹּר וְלוֹמַר, וְהַפָּרָשִׁיּוֹת מוֹכִיחוֹת, שֶׁאַף אוֹתוֹ מַעֲשֶׂה שֶׁל פָּרָשָׁה שְׁנִיָּה לֹא הָיְתָה כִּי אִם בִּשְׁבִיל מַעֲשֶׂה זֶה שֶׁל פָּרָשָׁה זֹאת רִאשׁוֹנָה:",2,0],[1,2,"אֶחָד מֵאַחַי. אֶחָד מֵחֲבֵרַי:",1,0],[1,2,"וָאֶשְׁאָלֵם עַל הַיְּהוּדִים וְגוֹ׳. שָׁאַלְתִּי לָהֶם עַל עִנְיַן פְּלֵיטַת הַיְּהוּדִים אֲשֶׁר נִשְׁאֲרוּ בִּירוּשָׁלַיִם מִן הַשֶּׁבִי שֶׁל בָּבֶל:",2,0],[1,2,"הַפְּלֵיטָה. עַל שֵׁם שֶׁנִּצּוֹלוּ מִגָּלוּת בָּבֶל:",3,0],[1,2,"וְעַל יְרוּשָׁלִָם. וְעַל עִנְיַן הָעִיר שָׁאַלְתִּי אֲלֵיהֶם:",4,0],[1,3,"וַיֹּאמְרוּ לִי. הֵשִׁיבוּ לִי עַל רִאשׁוֹן רִאשׁוֹן וְעַל אַחֲרוֹן אַחֲרוֹן, תְּחִלָּה עַל עִנְיַן הַיְּהוּדִים וְאַחַר כָּךְ עַל עִנְיַן הַחוֹמוֹת וְהַשְּׁעָרִים:",1,0],[1,3,"הַנִּשְׁאָרִים וְגוֹ׳. אוֹתָם הַיְּהוּדִים אֲשֶׁר נִשְׁאֲרוּ שָׁם בִּמְדִינַת יְרוּשָׁלַיִם, הֵם נְתוּנִים בְּרָעָה גְדוֹלָה וּבְחֶרְפָּה, לְפִי שֶׁהָעוֹבְדֵי כוֹכָבִים בּוֹזְזִים וְשׁוֹלְלִים אוֹתָם:",2,0],[1,3,"וְחוֹמַת יְרוּשָׁלִַם מְפֹרָצֶת. וְחוֹמַת הָעִיר הֲרֵי הִיא פְּרוּצָה, וְהַשְּׁעָרִים שְׂרוּפִים בָּאֵשׁ כְּקַדְמָתָן; שֶׁיִּשְׂרָאֵל לֹא בָּנוּ חוֹמוֹת הָעִיר וּשְׁעָרֶיהָ כִּי אִם בִּנְיַן בֵּית הַמִּקְדָּשׁ לְבַדּוֹ:",3,0],[1,3,"נִצְּתוּ. כְּמוֹ נוּצְתוּ (ספרים אחרים: נִצְּתוּ כמו נִתְּצוּ):",4,0],[1,4,"יָמִים. כַּמָּה יָמִים:",1,0],[1,5,"אָנָּא. לְשׁוֹן בַּקָּשָׁה וּתְחִנָּה:",1,0],[1,6,"קַשֶּׁבֶת. כְּמוֹ קוֹשֶׁבֶת כּוּ׳, כַּאֲשֶׁר יֹאמַר מֵ״אָהַב״ (בראשית כז:ט) ״אוֹהֵב״ (שמואל א יח:טז), כֵּן יֹאמַר מִן קָשַׁב קוֹשֵׁב וְקוֹשֶׁבֶת:",1,0],[1,7,"חֲבוֹל. שֵׁם דָּבָר, לְשׁוֹן הַשְׁחָתָה. וְחֵי״ת נִנְקְדָה בַּחֲטַף פַּתָּח. וְאֵינִי יָכוֹל לְפוֹתְרוֹ בִּלְשׁוֹן פָּעוּל, שֶׁאִם כֵּן הָיָה לוֹ לִנְקֹד חֵי״ת בְּקָמַץ גָּדוֹל:",1,0],[1,7,"חָבַלְנוּ. לְשׁוֹן הַשְׁחָתָה, כְּמוֹ (דניאל ו:כג) ״חֲבוּלָא לָא עֲבַדְתְּ״, וְכֵן חִבְּרוֹ מְנַחֵם:",2,0],[1,9,"אִם יִהְיֶה נִדַּחֲכֶם. כְּעִנְיָן שֶׁנֶּאֱמַר: ״אִם יִהְיֶה נִדַּחֲךָ וְגוֹ׳״ (דְּבָרִים ל:ד):",1,0],[1,11,"אָנָּא אֲדֹנָי תְּהִי נָא אָזְנְךָ קַשֶּׁבֶת. בִּתְחִלַּת תְּפִלָּתוֹ אָמַר לָשׁוֹן זֶה שֶׁל תְּחִנָּה, וְכֵן לְאַחַר תְּפִלָּתוֹ:",1,0],[1,11,"לְעַבְדְּךָ הַיּוֹם וְגוֹ׳. כָּךְ הָיָה מִתְפַּלֵּל עַל עַצְמוֹ:",2,0],[1,11,"לִפְנֵי הָאִישׁ הַזֶּה. לִפְנֵי הַמֶּלֶךְ:",3,0],[1,11,"מַשְׁקֶה. כְּמוֹ (בראשית מ:א) ״מַשְׁקֵה לְמֶלֶךְ מִצְרָיִם״, וְזֶה שֶׁפֵּרַשְׁתִּי לְמַעְלָה (עזרא ב:סג). כְּדִבְרֵי רַבּוֹתֵינוּ: הַתִּרְשָׁתָא הוּא נְחֶמְיָה:",4,0],[2,1,"לְאַרְתַּחְשַׁסְתְּא. הוּא דָּרְיָוֶשׁ (עזרא ד:ה), וְעַל שֵׁם הַמַּלְכוּת נִקְרָא כָּךְ:",1,0],[2,1,"יַיִן לְפָנָיו. הֵבִיאוּ יַיִן לִפְנֵי הַמֶּלֶךְ בֶּחָצֵר:",2,0],[2,1,"וָאֶשָּׂא אֶת הַיַּיִן. וְאָנֹכִי נָשָׂאתִי אֶת כּוֹס הַיַּיִן וּנְתַתִּיהָ לַמֶּלֶךְ. וְכָךְ הוּא הַמִּנְהָג, שֶׁהַמֵּבִיא יַיִן בַּחֲצַר הַמֶּלֶךְ אֵינוֹ נוֹשֵׂא וְנוֹתְנוֹ לַמֶּלֶךְ, אֲבָל שַׂר הַמַּשְׁקִים מְקַבֵּל כּוֹס הַיַּיִן מִיַּד הַמֵּבִיא וְהוּא נוֹשֵׂא וְנוֹתְנוֹ לַמֶּלֶךְ:",3,0],[2,1,"לֹא הָיִיתִי רַע לְפָנָיו. וַאֲנִי לֹא הָיִיתִי רָגִיל לִהְיוֹת רַע לְפָנָיו בְּרוֹעַ פָּנִים, כִּי אִם שָׂמֵחַ וְטוֹב לֵב, וְעַתָּה הָיִיתִי זוֹעֵף בְּרוֹעַ פָּנִים:",4,0],[2,2,"וְאַתָּה אֵינְךָ חוֹלֶה. וַהֲרֵי אֵין אַתָּה חוֹלֶה:",1,0],[2,2,"אֵין זֶה. אֵין הַמַּעֲשֶׂה הַזֶּה כִּי אִם רֹעַ לֵב, שֶׁיֵּשׁ בִּלְבָבְךָ עָלַי לַהֲמִיתֵנִי בְּסַם הַמָּוֶת בִּשְׁתִיַּת כּוֹס זֶה:",2,0],[2,2,"וָאִירָא הַרְבֵּה מְאֹד. וְנִתְיָרֵאתִי מְאֹד עַל כָּךְ, שֶׁלֹּא יַעֲלִיל עָלַי הַמֶּלֶךְ עֲלִילָה:",3,0],[2,3,"מַדּוּעַ לֹא יֵרְעוּ פָנַי. מַדּוּעַ לֹא יִהְיוּ פָנַי רָעִים:",1,0],[2,3,"אֲשֶׁר הָעִיר יְרוּשָׁלַיִם, שֶׁהִיא בֵּית קִבְרוֹת אֲבוֹתַי, חֲרֵבָה:",2,0],[2,4,"עַל מַה זֶּה אַתָּה מְבַקֵּשׁ. אֵי זֶה דָּבָר תְּבַקֵּשׁ מִמֶּנִּי וְאֶעֱשֶׂה לְךָ:",1,0],[2,4,"וָאֶתְפַּלֵּל. וְאָמַרְתִּי לִפְנֵי הַמֶּלֶךְ בִּתְפִלָּתִי: כֵּן יְהִי רָצוֹן מִלְּפָנֵי אֱלֹהֵי הַשָּׁמָיִם, שֶׁתְּמַלֵּא שְׁאֵלָתִי וּבַקָּשָׁתִי:",2,0],[2,5,"אֲשֶׁר תִּשְׁלָחֵנִי. שֶׁתִּתֵּן לִי רְשׁוּת לַעֲלוֹת לִירוּשָׁלַיִם וְלִבְנוֹתָהּ:",1,0],[2,6,"וַיֹּאמֶר לִי הַמֶּלֶךְ. בְּשָׁעָה שֶׁדִּבֵּר אֵלַי הַמֶּלֶךְ הָיְתָה אִשְׁתּוֹ הַמַּלְכָּה יוֹשֶׁבֶת אֶצְלוֹ:",1,0],[2,6,"וְהַשֵּׁגַל. אִשְׁתּוֹ הַמַּלְכָּה, כְּעִנְיָן שֶׁנֶּאֱמַר (דניאל ה:ב) ״שֵׁגְלָתֵהּ וּלְחֵנָתֵהּ״. שֶׁכֵּן נוֹהֵג הַמִּקְרָא לִכְתֹּב הַמַּלְכָּה אֵצֶל הַפִּלֶגֶשׁ ״נָשָׁיו וּפִילַגְשָׁיו״ (דברי הימים ב יא:כא), כְּמוֹ ״מְלָכוֹת וּפִילַגְשִׁים״ (שיר השירים ו:ט):",2,0],[2,6,"עַד מָתַי יִהְיֶה מַהֲלָכְךָ. מָתַי תִּרְצֶה שֶׁיְּהֵא מַהֲלָכְךָ וּמַסָּעֲךָ?:",3,0],[2,6,"וּמָתַי תָּשׁוּב. וּמָתַי דַּעְתְּךָ לַחֲזוֹר?:",4,0],[2,6,"יִשְׁלָחֵנִי. נָתַן לִי רְשׁוּת לָלֶכֶת:",5,0],[2,6,"וָאֶתְּנָה לוֹ זְמָן. נָתַתִּי לוֹ זְמָן לַחֲזוֹר:",6,0],[2,7,"אִגְּרוֹת יִתְּנוּ לִי. סוֹפְרֶיךָ עַל רְשׁוּתְךָ וְדַעְתְּךָ, חֲתוּמוֹת בְּחוֹתָמְךָ, עַל פַּחֲוַת עֵבֶר הַנָּהָר שֶׁל צַד אֶרֶץ יִשְׂרָאֵל:",1,0],[2,7,"אֲשֶׁר יַעֲבִירוּנִי. וִיתַיְּרוּנִי לְשָׁלוֹם:",2,0],[2,7,"עַד אֲשֶׁר אָבוֹא. לִירוּשָׁלַיִם אֲשֶׁר בִּמְדִינַת יְהוּדָה:",3,0],[2,8,"וְאִגֶּרֶת אֶל אָסָף. וְתִשְׁלַח כְּתַב אִגֶּרֶת אֶל אָסָף:",1,0],[2,8,"שׁוֹמֵר הַפַּרְדֵּס. מְמֻנֶּה הָיָה עַל הַיְּעָרִים אֲשֶׁר לַמֶּלֶךְ:",2,0],[2,8,"לְקָרוֹת. מִשְׁקַל חָזָק לַעֲשׂוֹת תִּקְרוֹת וְקוֹרוֹת לְשַׁעֲרֵי בִּירוֹת הַר הַבַּיִת, שֶׁהֲרֵי בֵּית הַמִּקְדָּשׁ בָּנוּ בְּבִנְיָנוֹ, אֲבָל שַׁעֲרֵי חוֹמוֹת הַר הַבַּיִת וְחוֹמַת הֶחָצֵר אֲשֶׁר סָבִיב בֵּית הַמִּקְדָּשׁ לֹא בָּנוּ עֲדַיִן:",3,0],[2,8,"וּלְחוֹמַת הָעִיר. וְלַעֲשׂוֹת קוֹרוֹת לְחוֹמַת הָעִיר:",4,0],[2,8,"וְלַבַּיִת אֲשֶׁר אָבוֹא אֵלָיו. וְלַעֲשׂוֹת בַּיִת אֲשֶׁר אֵשֵׁב בּוֹ לְצָרְכִּי:",5,0],[2,8,"וַיִּתֶּן לִי הַמֶּלֶךְ. אֶת כָּל אֲשֶׁר שָׁאַלְתִּי מִמֶּנּוּ:",6,0],[2,8,"כְּיַד. כְּפִי יָדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהָיְתָה טוֹבָה עָלָי לְהַצְלִיחֵנִי:",7,0],[2,9,"וָאֶתְּנָה לָהֶם אֵת אִגְּרוֹת הַמֶּלֶךְ. לְמַעַן יְתַיְּרוּנִי לְשָׁלוֹם:",1,0],[2,9,"שָׂרֵי חַיִל וּפָרָשִׁים. שָׁלַח הַמֶּלֶךְ עִמִּי לִכְבוֹדִי, לְמַעַן אֵלֵךְ לְשָׁלוֹם:",2,0],[2,10,"וַיִּשְׁמַע סַנְבַלַּט וְגוֹ׳. כַּאֲשֶׁר שָׁמְעוּ שֶׁבָּאתִי לְבַקֵּשׁ טוֹבָה עַל יִשְׂרָאֵל וְלִבְנוֹת חוֹמוֹת יְרוּשָׁלַיִם, וַיֵּרַע בְּעֵינֵיהֶם, כִּי הָיוּ צָרֵי יְהוּדָה וּבִנְיָמִין (עזרא ד:א):",1,0],[2,11,"וָאֱהִי שָׁם יָמִים שְׁלֹשָׁה. הָיִיתִי בִּירוּשָׁלַיִם יָמִים שְׁלֹשָׁה וּלְסוֹף שְׁלֹשֶׁת יָמִים קַמְתִּי בַלַּיְלָה אֲנִי וַאֲנָשִׁים מְעַטִּים עִמִּי וְלֹא הִגַּדְתִּי לְשׁוּם אָדָם אֶת אֲשֶׁר נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא בְּלִבִּי:",1,0],[2,12,"וּבְהֵמָה אֵין עִמִּי. כִּי כָל הָאֲנָשִׁים מוּעָטִים אֲשֶׁר עִמִּי הָלְכוּ בְרַגְלֵיהֶם, אֲבָל אֲנִי לְבַדִּי הָיִיתִי רוֹכֵב עַל בְּהֵמָה; שֶׁלֹּא הָיוּ רוֹצִים לִרְכֹּב עַל סוּסֵיהֶם, לְמַעַן יִהְיוּ יוֹצְאִים מִן הָעִיר בְּצִנְעָא, בְּלֹא יְדִיעַת אָדָם. וְהֵם הָלְכוּ לִשְׁבֹּר וּלְהַפִּיל חוֹמוֹת הָעִיר בַּלַּיְלָה, וּלְהַרְבּוֹת פִּרְצוֹתֶיהָ, לְמַעַן יִהְיוּ בְּנֵי הָעִיר לְמָחָר לְהוּטִים וּמַסְכִּימִים בְּעֵצָה אַחַת עִם נְחֶמְיָה לִבְנוֹת חוֹמוֹת הָעִיר, וְכֵן מוֹכִיחַ הַמַּעֲשֶׂה בְּתוֹךְ הַפָּרָשָׁה:",1,0],[2,13,"וָאֵצְאָה בְשַׁעַר הַגַּיְא. יָצָאתִי בְּאוֹתוֹ שַׁעַר בַּלַּיְלָה עִם הָאֲנָשִׁים אֲשֶׁר עִמִּי לְצַד אוֹתוֹ מָקוֹם שֶׁל עֵין הַתַּנִּין וּלְאוֹתוֹ שַׁעַר הָאַשְׁפֹּת שֶׁבְּחוֹמוֹת הָעִיר. וְהָיִיתִי פּוֹרֵץ בַּחוֹמָה, וְהַחוֹמָה הָיְתָה נוֹחָה לְהַפִּילָהּ וְלִפְרֹץ בָּהּ לְפִי שֶׁהָיְתָה שְׂרוּפָה בָאֵשׁ:",1,0],[2,13,"אֲשֶׁר הֵם פְּרוּצִים. שֶׁהֵם אוֹתָם מְקוֹמוֹת שֶׁהָיוּ פְּרוּצִים וְהֵם פָּרְצוּ בָּהֶם יוֹתֵר:",2,0],[2,14,"וָאֶעֱבֹר אֶל שַׁעַר הָעַיִן. וְרָצִיתִי לַעֲבֹר אֶל אוֹתָן מְקוֹמוֹת שֶׁבְּחוֹמַת הָעִיר וּבְאוֹתָן פְּרָצוֹת, וְאֵין מָקוֹם בְּאוֹתָן פְּרָצוֹת לַעֲבֹר בֵּינֵיהֶם רוֹכֵב עַל הַבְּהֵמוֹת, שֶׁהָיוּ פְּרָצוֹת קְטַנּוֹת:",1,0],[2,15,"וָאֱהִי עוֹלֶה. וְהָיִיתִי עוֹלֶה מִצַּד אֶחָד בַּלַּיְלָה, וְהָיִיתִי שׁוֹבֵר בַּחוֹמָה עִם הָאֲנָשִׁים אֲשֶׁר עִמִּי:",1,0],[2,15,"וָאָשׁוּב וָאָבוֹא. וְכַאֲשֶׁר חָזַרְתִּי בָּאתִי דֶּרֶךְ שַׁעַר הַגַּיְא:",2,0],[2,16,"וְהַסְּגָנִים. אֲשֶׁר בָּעִיר, לֹא הָיוּ יוֹדְעִין לְהֵיכָן הָלַכְתִּי וְאֶת הַמַּעֲשֶׂה אֲשֶׁר עָשִׂיתִי׃",1,0],[2,16,"עַד כֵּן. עַד עַתָּה:",2,0],[2,17,"וָאוֹמַר אֲלֵיהֶם. לְמָחָר אָמַרְתִּי לָהֶם:",1,0],[2,17,"וְלֹא נִהְיֶה עוֹד חֶרְפָּה. שֶׁלֹּא יִהְיוּ צָרֵינוּ בּוֹזְזִים וְשׁוֹלְלִים אוֹתָנוּ:",2,0],[2,18,"אֶת יַד אֱלֹהַי. אֲשֶׁר נָתַן לִי חֵן וְהַצְלָחָה לִפְנֵי הַמֶּלֶךְ:",1,0],[2,18,"לַטּוֹבָה. הַכֹּל נִתְכַּוְּנוּ לְטוֹבָה, לִבְנוֹת חוֹמַת הָעִיר וּמִגְדָּלֶיהָ:",2,0],[2,19,"וַיַּלְעִיגוּ. כַּאֲשֶׁר שָׁמְעוּ הַצָּרִים שְׁמוּעַת בִּנְיַן חוֹמַת הָעִיר, הָיוּ מַלְעִיגִים עָלֵינוּ:",1,0],[2,19,"הֲעַל הַמֶּלֶךְ. אִם עַל הַמֶּלֶךְ אַתֶּם מוֹרְדִים לִבְנוֹת חוֹמַת הָעִיר כְּדֵי לִמְרוֹד בּוֹ:",2,0],[2,20,"וְלָכֶם אֵין חֵלֶק. מַה לָּכֶם בְּבִנְיַן חוֹמַת הָעִיר הַזֹּאת כִּי אֵין לָכֶם חֵלֶק בָּהּ:",1,0],[3,1,"שַׁעַר הַצֹּאן. כָּךְ שְׁמוֹ שֶׁל שַׁעַר:",1,0],[3,1,"הֵמָּה קִדְּשׁוּהוּ. לְאוֹתוֹ שַׁעַר בִּקְדֻשַּׁת הָעִיר:",2,0],[3,1,"דַּלְתוֹתָיו. שֶׁל שַׁעַר:",3,0],[3,1,"וְעַד מִגְדַּל הַמֵּאָה. כָּךְ שְׁמוֹ שֶׁל מִגְדָּל:",4,0],[3,2,"וְעַל יָדוֹ. אֵצֶל יָדוֹ, בְּסָמוּךְ לוֹ שֶׁל כָּל בּוֹנֶה וּבוֹנֶה שֶׁבָּנוּ אוֹתוֹ בְּבִנְיָן שֶׁל שַׁעַר הַצֹּאן:",1,0],[3,2,"בָּנוּ אַנְשֵׁי יְרֵחוֹ. שֶׁכָּךְ הָיוּ מִנְהָגָם: הַלָּלוּ הָיוּ בּוֹנִים כָּאן בְּחוֹמַת הָעִיר עַד תַּשְׁלוּם בִּנְיָנָהּ הַמּוּטָל עֲלֵיהֶם, וְהָאֲחֵרִים הָיוּ בּוֹנִים סָמוּךְ לַבִּנְיָן הָרִאשׁוֹן, וְכָךְ הָיָה מִנְהָגָם בָּזֶה אַחַר זֶה עַד שֶׁנִּבְנֵית כָּל הַחוֹמָה:",2,0],[3,2,"וְעַל. כְּמוֹ (במדבר ב:כ) ״וְעָלָיו מַטֵּה מְנַשֶּׁה״, בְּסָמוּךְ, וְכֵן פִּתְרוֹנוֹ: סָמוּךְ לְבִנְיָן יָדוֹ. וְהַמִּקְרָא לֹא דִקְדֵּק בִּלְשׁוֹנוֹ, פְּעָמִים שֶׁהוּא אוֹמֵר: עַל יָדוֹ, וּפְעָמִים שֶׁהוּא אוֹמֵר: עָלָיו, וְאַחֲרָיו הֶחֱזִיק:",3,0],[3,3,"וְאֵת שַׁעַר הַדָּגִים. כָּךְ שֵׁם הַשַּׁעַר:",1,0],[3,3,"הֵמָּה קֵרוּהוּ. נָתְנוּ הַקּוֹרוֹת וְתִקְרוֹת עַל הַשַּׁעַר:",2,0],[3,3,"קֵרוּהוּ. מִשְׁקָל חָזָק, כְּמוֹ מִן קָרָה, דּוּגְמַת ״הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו״ (תהילים קד:ג). וְקוּ״ף שֶׁל קֵרוּהוּ אֵינָהּ נְהוּגָה לִינָּקֵד בְּחִירִ״ק בְּעִנְיָן זֶה מִפְּנֵי רֵי״שׁ שֶׁל אַחֲרֶיהָ, כְּמוֹ ״בֵּרַךְ״ (תהילים י:ג), ״חֵרֵף עֹשֵׂהוּ״ (משלי יז:ה), ״וּבֵרַכְתִּיהָ וְהָיְתָה לְגוֹיִם״ (בראשית יז:טז), ״וְזֵרִיתִים בָּאֲרָצוֹת״ (יחזקאל כט:יב):",3,0],[3,3,"מַנְעוּלָיו. מַסְגְּרָיו שֶׁשְׁוִירְלָ״ץ בְּלַעַ״ז:",4,0],[3,4,"הֶחֱזִיק. לִבְנוֹת הַבִּנְיָן:",1,0],[3,5,"הַתְּקוֹעִים. כָּךְ הָיוּ נִקְרָאִים עַל שֵׁם מְקוֹמָם שֶׁהָיָה תְּקוֹעַ:",1,0],[3,5,"אַדִּירֵיהֶם. עֲשִׁירִים שֶׁל תְּקוֹעַ:",2,0],[3,5,"לֹא הֵבִיאוּ צַוָּרָם. לֹא סִיְּעוּ בַּעֲבוֹדָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, לִבְנוֹת חוֹמַת הָעִיר:",3,0],[3,6,"וְאֵת שַׁעַר הַיְשָׁנָה. כָּךְ שְׁמָהּ:",1,0],[3,7,"לְכִסֵּא פַּחַת עֵבֶר הַנָּהָר. כִּסֵּא אֶחָד בָּנָה כְּדֵי לֵישֵׁב בּוֹ אוֹתוֹ פַּחַת שֶׁל עֵבֶר הַנָּהָר:",1,0],[3,8,"צוֹרְפִים. אוֹתָהּ מִשְׁפָּחָה הָיְתָה נִקְרֵאת עַל שֵׁם אוּמָּנוּתָם:",1,0],[3,8,"וַיַּעַזְבוּ יְרוּשָׁלִַם. מִלְּאוּהָ עָפָר עַד הַחוֹמָה הָרְחָבָה, כְּדֵי לְהַחֲזִיקָהּ:",2,0],[3,9,"שַׂר חֲצִי פֶּלֶךְ יְרוּשָׁלִָם. שַׂר הָיָה עַל חֲצִי הָעָם שֶׁבִּירוּשָׁלַיִם, פֶּלֶךְ לְשׁוֹן דֻּכָּסוּת וּמַלְכוּת:",1,0],[3,10,"וְנֶגֶד בֵּיתוֹ. נָפַל חֶלְקוֹ לִבְנוֹת שֶׁהָיָה בֵּיתוֹ סָמוּךְ לְאוֹתוֹ מָקוֹם שֶׁל חוֹמַת הָעִיר:",1,0],[3,11,"מִדָּה שֵׁנִית. כְּאוֹתָהּ מִדָּה אֲשֶׁר בָּנָה חֲבֵירוֹ שֶׁל מַעְלָה, גַּם הוּא בָּנָה כְּמוֹתוֹ, מִדָּה שֵׁנִית בְּבִנְיַן הַחוֹמָה. אֵינוֹ נוֹפֵל לוֹמַר לְשׁוֹן מִדָּה בְּבִנְיַן הַשְּׁעָרִים, לְפִי שֶׁאֵין לָהֶם כִּי אִם בְּבִנְיַן חֵלֶק שֶׁל חוֹמָה, שֶׁלֹּא מָצִינוּ בְּכָל הַפָּרָשָׁה בְּבִנְיַן הַשְּׁעָרִים לְשׁוֹן מִדָּה:",1,0],[3,11,"וְאֵת מִגְדַּל הַתַּנּוּרִים. גַּם הוּא בָּנָה אוֹתוֹ מִגְדָּל שֶׁשְּׁמוֹ כָּךְ. כָּל הַמִּגְדָּלִים הַלָּלוּ שֶׁבַּפָּרָשָׁה הָיוּ בְנוּיִים בְּחוֹמַת הָעִיר סָבִיב:",2,0],[3,12,"הוּא וּבְנוֹתָיו. שַׁלּוּם וּבְנוֹתָיו הֶחֱזִיקוּ לִבְנוֹת הַבִּנְיָן:",1,0],[3,13,"עַד שַׁעַר הַשְּׁפוֹת. וְשַׁעַר הָאַשְׁפּוֹת לֹא הָיָה בִּכְלָל:",1,0],[3,15,"שַׂר פֶּלֶךְ הַמִּצְפָּה. שַׂר וְדֻוכּוֹס הַמִּצְפָּה:",1,0],[3,15,"הוּא יִבְנֶנּוּ. הוּא הָיָה בּוֹנֶה אוֹתוֹ שַׁעַר:",2,0],[3,15,"וִיטַלְלֶנּוּ. וְהוּא הָיָה מְסַכֵּךְ אוֹתוֹ, לְשׁוֹן מְטַלַלְתָּא:",3,0],[3,15,"וְאֵת חוֹמַת בְּרֵכַת הַשֶּׁלַח. שֶׁהוּא נוֹטֶה לְצַד גַּן הַמֶּלֶךְ:",4,0],[3,15,"וְעַד הַמַּעֲלוֹת. הֵם הָיוּ מַכִּירִים מְקוֹמוֹת הַלָּלוּ:",5,0],[3,16,"בֵּית צוּר. שֵׁם מָקוֹם:",1,0],[3,17,"לְפִלְכּוֹ. מֵאוֹתָהּ שְׂרָרָה חֲצִי פֶלֶךְ בָּנָה בִּנְיָן זֶה. לְפִלְכּוֹ כָּ״ף דְּגוּשָׁה, כַּאֲשֶׁר יֹאמַר מִן מֶלֶךְ מַלְכּוֹ, מִן עֶבֶד עַבְדּוֹ, כֵּן יֹאמַר מִן פֶּלֶךְ פִּלְכּוֹ; שֶׁאוֹת אַחֲרוֹנָה שֶׁל שֵׁם דָּבָר מֵאוֹתִיּוֹת בג״ד כפ״ת דְּגוּשׁוֹת:",1,0],[3,18,"אֲחֵיהֶם. הַלְוִיִּם:",1,0],[3,19,"מִנֶּגֶד עֲלוֹת הַנֶּשֶׁק. כְּנֶגֶד אוֹתוֹ מָקוֹם שֶׁהָיוּ עוֹלִים הַגִּבּוֹרִים אֶל הַנֶּשֶׁק. לְפִי פְּשׁוּטוֹ שֶׁל מִקְרָא נִרְאֶה שֶׁהָיָה שָׁם מָקוֹם אֶחָד בְּסָמוּךְ לַחוֹמָה וּכְלֵי זַיִן שֶׁל נֶשֶׁק הַגִּבּוֹרִים הָיוּ נוֹתְנִין (ספרים אחרים: נְתוּנִים) שָׁם כְּעִנְיָן שֶׁנֶּאֱמַר ״עָרֵי מִבְצָר וְהַנֶּשֶׁק״ (מלכים ב י:ב):",1,0],[3,19,"הַמִּקְצוֹעַ. לְקֶרֶן זָוִית שֶׁל חוֹמָה׃",2,0],[3,20,"הֶחֱרָה. פִּתְרוֹנוֹ לְפִי עִנְיָנוֹ, וְכֶפֶל לָשׁוֹן הוּא עַל הַחִזּוּק:",1,0],[3,21,"מִפֶּתַח בֵּית אֶלְיָשִׁיב וְעַד תַּכְלִית וְגוֹ׳. מִנֶּגֶד אוֹתוֹ בַּיִת בָּנָה בִּנְיָנוֹ:",1,0],[3,23,"נֶגֶד בֵּיתָם. שֶׁהָיָה שָׁם בְּסָמוּךְ לַחוֹמָה:",1,0],[3,25,"וְהַמִּגְדָּל הַיּוֹצֵא. מִגְדָּל אֶחָד הָיָה בַּחוֹמָה שֶׁהוּא יוֹצֵא וּבוֹלֵט מִבִּפְנִים:",1,0],[3,26,"וְהַנְּתִינִים הָיוּ יֹשְׁבִים בָּעֹפֶל. וְהַנְּתִינִים הָיוּ יוֹשְׁבִים בְּאוֹתוֹ מָחוֹז, וְהָיוּ בּוֹנִים אוֹתוֹ מָחוֹז שֶׁלָּהֶם שֶׁהָיָה סָמוּךְ לַחוֹמָה עַד נֶגֶד שַׁעַר הַמַּיִם שֶׁל צַד הַמִּזְרָח:",1,0],[3,28,"אִישׁ לְנֶגֶד בֵּיתוֹ. כָּל אֶחָד הָיָה בּוֹנֶה כְּנֶגֶד בֵּיתוֹ:",1,0],[3,30,"וְחָנוּן בֶּן צָלָף הַשִּׁשִּׁי. בָּנִים הַרְבֵּה הָיוּ לוֹ לְצָלָף, וְחָנוּן הוּא הַשִּׁשִּׁי:",1,0],[3,30,"מִדָּה שֵׁנִי. כְּמוֹ ״שֵׁנִית״ (נחמיה ג:כז):",2,0],[3,30,"נִשְׁכָּתוֹ. כְּמוֹ לִשְׁכָּתוֹ, לִשְׁכָּה אַחַת הָיְתָה לוֹ שָׁם סָמוּךְ לַחוֹמָה:",3,0],[3,31,"בֶּן הַצּוֹרְפִי. אִישׁ הַצּוֹרֵף, וְנִקְרָא שֶׁל שֵׁם אוּמָנוּתוֹ:",1,0],[3,32,"וּבֵין עֲלִיַּת הַפִּנָּה לְשַׁעַר הַצֹּאן. תְּחִלַּת הַבִּנְיָן הִתְחִילוּ לִבְנוֹת שַׁעַר הַצֹּאן, שֶׁנֶּאֱמַר ״וַיִּבְנוּ אֶת שַׁעַר הַצֹּאן וְגוֹ׳״ (נחמיה ג:א). כָּךְ הָיוּ בּוֹנִין הַחוֹמָה מִסָּבִיב בָּזֶה אַחַר זֶה:",1,0],[3,34,"לִפְנֵי אֶחָיו וְחֵיל שֹׁמְרוֹן. לִפְנֵי חֲבֵירָיו וְחֵיל שֹׁמְרוֹן שֶׁהָיוּ צָרֵי יְהוּדָה:",1,0],[3,34,"מָה הַיְּהוּדִים. מַדּוּעַ הַיְּהוּדִים כָּךְ הֵם עוֹשִׂים?:",2,0],[3,34,"הָאֲמֵלָלִים. עִנְיַן חֲלָשׁוּת וְרִפְיוֹן:",3,0],[3,34,"הֲיַעַזְבוּ לָהֶם. וְכִי הֵם סְבוּרִים אֲשֶׁר יַעַזְבוּ וְיַנִּיחוּ לָהֶם הָעוֹבְדֵי כוֹכָבִים לִבְנוֹת?:",4,0],[3,34,"הֲיִזְבָּחוּ. אִם יִזְבְּחוּ לָהֶם אֶת זִבְחֵיהֶם תָּמִיד כְּמוֹ שֶׁהֵם סְבוּרִים:",5,0],[3,34,"הַיְכַלּוּ בַיּוֹם. אִם יְכַלּוּ וְיַשְׁלִימוּ מְלַאכְתָּם אֲשֶׁר הִתְחִילוּ בְּיוֹם א׳? לוֹמַר שֶׁלֹּא יַנִּיחוּם הָעוֹבְדֵי כוֹכָבִים לִגְמֹר אֶת בִּנְיָנָם:",6,0],[3,34,"הֲיְחַיּוּ. אִם יְחַיּוּ וִיתַקְּנוּ וְיַחֲזִירוּ הָאֲבָנִים לְקַדְמָתָן לִהְיוֹת קָשׁוֹת וַחֲזָקוֹת מִן הֶעָפָר:",7,0],[3,34,"מֵעֲרֵמוֹת. עִנְיַן חֳמָרִים וְתִלִּים:",8,0],[3,34,"וְהֵמָּה שְׂרוּפוֹת. וְהָאֲבָנִים הָיוּ שְׂרוּפוֹת וְנַעֲשֵׂית עָפָר. כָּךְ הָיוּ מַלְעִיגִים וּמִתְלוֹצְצִים עַל בִּנְיַן הַחוֹמָה, שֶׁהָיוּ בּוֹנִין מִן הָאֲבָנִים שְׂרוּפוֹת שֶׁנָּפְלוּ לָאָרֶץ מִן הָאֵשׁ כַּאֲשֶׁר נִשְׂרְפָה יְרוּשָׁלָיִם:",9,0],[3,35,"וְטוֹבִיָּה הָעַמּוֹנִי אֶצְלוֹ. טוֹבִיָּה הָיָה אֶצְלוֹ שֶׁל סַנְבַלָּט:",1,0],[3,35,"וַיֹּאמֶר. וְכָךְ הָיָה אוֹמֵר וּמַלְעִיג:",2,0],[3,35,"גַּם אֲשֶׁר הֵם בּוֹנִים. אַף הַבִּנְיָן הַזֶּה אֲשֶׁר הֵם בּוֹנִים:",3,0],[3,35,"אִם יַעֲלֶה שׁוּעָל. עַל הַבִּנְיָן לִפְרֹץ חוֹמַת הָעִיר, מַה יְּהֵא עָלָיו? לוֹמַר שֶׁאֵין לַבִּנְיָן תַּקָּנָה, וְכָל מִי שֶׁיִּרְצֶה יָבֹא וְיִפְרֹץ בּוֹ:",4,0],[3,36,"שְׁמַע אֱלֹהֵינוּ. כַּאֲשֶׁר שָׁמַעְתִּי בְּלַעֲגָם עָלֵינוּ הִתְפַּלַּלְתִּי תְּפִלָּה זֹאת:",1,0],[3,36,"בְּאֶרֶץ שִׁבְיָה. שֶׁיִּגְלוּ מֵעַל אַדְמָתָם כַּאֲשֶׁר גָּלִינוּ:",2,0],[3,37,"וְאַל תְּכַס. כְּמוֹ וְאַל תְּכַסֶּה, דּוּגְמַת ״וְסוֹד אַחֵר אַל תְּגַל״ (משלי כה:ט), כְּמוֹ אַל תְּגַלֶּה:",1,0],[3,37,"כִּי הִכְעִיסוּ. אֲשֶׁר הִכְעִיסוּ נֶגֶד הַבּוֹנִים לְהַלְעִיגָם:",2,0],[3,38,"וַתִּקָּשֵׁר. כַּאֲשֶׁר נִתְקַשְּׁרָה הַחוֹמָה וְנִבְנֵית עַד חֶצְיָהּ, אָז הָיָה לֵב הָעָם לָהוּט וּמָשׁוּךְ לַעֲשׂוֹת בִּנְיַן הַחוֹמָה:",1,0],[4,1,"כִּי עָלְתָה אֲרוּכָה. שֶׁנִּבְנְתָה הַחוֹמָה:",1,0],[4,1,"אֲרוּכָה. עִנְיַן חוֹבֶשׁ וּתְרוּפָה:",2,0],[4,1,"כִּי הֵחֵלּוּ הַפְּרוּצִים לְהִסָּתֵם. אֲשֶׁר הִתְחִילוּ אַנְשֵׁי הָעִיר שֶׁהָיוּ פְּרוּצִים עַד עַתָּה מֵאֵין חוֹמָה הָיוּ עַתָּה סְתוּמִים בְּבִנְיַן הַחוֹמָה:",3,0],[4,2,"וְלַעֲשׂוֹת לוֹ תּוֹעָה. לַעֲשׂוֹת לוֹ בְּבִנְיַן הַחוֹמָה קִלְקוּל וְהַשְׁחָתָה. תּוֹעָה כְּמוֹ ״וּלְדַבֵּר אֶל ה׳ תּוֹעָה״ (ישעיהו לב:ו):",1,0],[4,3,"עֲלֵיהֶם. עַל הַבּוֹנִים:",1,0],[4,3,"מִפְּנֵיהֶם. מִפְּנֵי הָאוֹיְבִים:",2,0],[4,4,"וַיֹּאמֶר יְהוּדָה. כָּךְ הָיוּ אוֹמְרִים וּמִתְאוֹנְנִים אַנְשֵׁי יְהוּדָה:",1,0],[4,4,"כָּשַׁל כֹּחַ הַסַּבָּל. הַסּוֹבְלִים וְעוֹמְסִים הָאֲבָנִים וְהָעֵצִים לְבִנְיַן הַחוֹמָה נִכְשְׁלוּ בְכֹחָם, שֶׁאֵין בָּהֶם כֹּחַ לִבְנוֹת מִפְּנֵי הָאוֹיְבִים:",2,0],[4,4,"וְעָפָר הַרְבֵּה. עֲדַיִן יֵשׁ טִיט וְחֹמֶר הַרְבֵּה לִיתֵּן בְּבִנְיַן הַחוֹמָה, לוֹמַר שֶׁעֲדַיִן הַמְּלָאכָה גְּדוֹלָה עָלֵינוּ לִבְנוֹת, וַאֲנַחְנוּ לֹא נוּכַל לִבְנוֹת בַּחוֹמָה מִפְּנֵי פַּחַד הָאוֹיְבִים:",3,0],[4,5,"וַיֹּאמְרוּ צָרֵינוּ. כָּךְ הָיָה נְחֶמְיָה מְסַפֵּר וְהוֹלֵךְ:",1,0],[4,5,"לֹא יֵדְעוּ וְלֹא יִרְאוּ. כָּךְ הָיוּ אוֹמְרִים צָרֵינוּ עָלֵינוּ: לֹא יֵדְעוּ וְלֹא יַכִּירוּ יִשְׂרָאֵל בָּנוּ עַד אֲשֶׁר נָבוֹא פִּתְאוֹם לְתוֹכָם וְנַהֲרֹג אוֹתָם, וּבְדָבָר זֶה נִשְׁבֹּת וּנְבַטֵּל הַבִּנְיָן:",2,0],[4,6,"וַיְהִי כַּאֲשֶׁר בָּאוּ הַיְּהוּדִים. וְעַתָּה נֶאֶסְפוּ הַצָּרִים אֲשֶׁר נִתְקַשְּׁרוּ יַחַד לָבֹא לְהִלָּחֵם בָּנוּ עִם הַיְּהוּדִים אֲשֶׁר הָיוּ בֵּינוֹתָם בְּאַרְצוֹתָם, וְאוֹתָם הַיְּהוּדִים אֲשֶׁר נִתְחַבְּרוּ עִמָּהֶם בָּאוּ לִפְנֵי הַחַיִל כְּדֶרֶךְ אַנְשֵׁי הַמִּלְחָמָה לְדַבֵּר אֵלֵינוּ. וּבָעִנְיָן הַזֶּה הֶעֱרִימוּ הַיְּהוּדִים אֶת הָאוֹיְבִים וַיְהִי כַּאֲשֶׁר בָּאוּ הַיְּהוּדִים הַיּוֹשְׁבִים אֶצְלָם וְגוֹ׳:",1,0],[4,6,"וַיֹּאמְרוּ לָנוּ עֶשֶׂר פְּעָמִים. הִתְרוּ בָּנוּ אוֹתָם הַיְּהוּדִים עַד עֶשֶׂר פְּעָמִים לְהִלָּחֵם בְּאוֹיְבֵינוּ כִּי הֵם בָּאִים לַמִּלְחָמָה, וְכָךְ אָמְרוּ לָנוּ: מִכָּל הַמְּקוֹמוֹת וְגוֹ׳ מִכָּל אוֹתָן הַמְּקוֹמוֹת שֶׁתִּהְיוּ נְפוֹצִים שָׁם בְּבִנְיַן הַחוֹמָה אָנָה וָאָנָה, תִּהְיוּ זְהִירִים לִהְיוֹת נֶאֱסָפִים יַחַד עַד אֲשֶׁר תָּשׁוּבוּ עָלֵינוּ בְּיַחַד לְהִלָּחֵם בָּנוּ:",2,0],[4,7,"וָאַעֲמִיד מִתַּחְתְּיוֹת. לַחוֹמָה, כַּאֲשֶׁר שָׁמַעְתִּי דִּבְרֵיהֶם הֶעֱמַדְתִּי מִתַּחְתְּיוֹת לְאוֹתוֹ מָקוֹם סָבִיב לִירוּשָׁלַיִם מֵאֲחוֹרֵי לְחוֹמַת הָעִיר בַּצְּחִיחִים:",1,0],[4,7,"לְמִשְׁפָּחוֹת. מִן הָעָם מִגִּבּוֹרִים שֶׁבָּהֶם, עִם כְּלֵי זַיִן שֶׁבָּהֶם, לְהִלָּחֵם בְּאוֹיְבֵינוּ כַּאֲשֶׁר יָבֹאוּ:",2,0],[4,7,"וָאַעֲמִיד מִתַּחְתְּיוֹת וְגוֹ׳ וָאַעֲמִיד אֶת הָעָם וְגוֹ׳. מִקְרָא זֶה דּוּגְמַת ״וְהָיוּ הַמַּיִם אֲשֶׁר תִּקַּח מִן הַיְאֹר וְגוֹ׳ וְהָיוּ לְדָם בַּיַּבָּשֶׁת״ (שמות ד:ט), ״כִּי הִנֵּה אוֹיְבֶיךָ ה׳ כִּי הִנֵּה אוֹיְבֶיךָ יֹאבֵדוּ״ (תהלים צב:י), ״עוּרִי עוּרִי דְּבוֹרָה עוּרִי עוּרִי דַּבְּרִי שִׁיר״ (שופטים ה:יב), ״לֹא לָנוּ ה׳ לֹא לָנוּ״ (תהלים קטו:א):",3,0],[4,8,"וָאֵרֶא וָאָקוּם. וְכַאֲשֶׁר רָאִיתִי הָאוֹיְבִים בָּאִים, קַמְתִּי לְדַבֵּר אֶל הַחוֹרִים וְהַסְּגָנִים לְזָרְזָם לְהִלָּחֵם בְּאוֹיְבֵינוּ:",1,0],[4,8,"עַל אֲחֵיכֶם. בִּשְׁבִיל אֲחֵיכֶם:",2,0],[4,9,"כִּי נוֹדַע לָנוּ. הַדָּבָר אֲשֶׁר בָּאוּ לְהִלָּחֵם בָּנוּ:",1,0],[4,9,"וַנָּשָׁב כֻּלָּנוּ. חָזַרְנוּ כֻּלָּנוּ מִמָּקוֹם שֶׁנֶּאֱסַפְנוּ יַחַד לִקְרַאת הָאוֹיְבִים, כָּל אֶחָד וְאֶחָד בִּמְלַאכְתּוֹ לְבִנְיַן הַחוֹמָה:",2,0],[4,10,"וַיְהִי מִן הַיּוֹם הַהוּא. וּמֵאוֹתוֹ יוֹם וָהָלְאָה הָיוּ חֲצִי הַגִּבּוֹרִים עוֹשִׂים בְּבִנְיַן הַחוֹמָה, וּשְׁאָר חֲצִי הַגִּבּוֹרִים הָיוּ מְזֻיָּנִים בִּכְלֵי זֵינָם לִשְׁמֹר אֲחֵיהֶם הָעוֹשִׂים בַּמְּלָאכָה:",1,0],[4,10,"וְהָרְמָחִים. וָ״ו יְתֵרָה, כְּמוֹ וָ״ו שֶׁל ״וְאַיָּה וַעֲנָה״ (בראשית לו:כד):",2,0],[4,10,"וְהַשָּׂרִים. הָיוּ מְחֻבָּרִים אַחֲרֵי כָּל שֵׁבֶט יְהוּדָה, לִהְיוֹת זְהִירִים בַּמִּלְחָמָה:",3,0],[4,11,"הַבּוֹנִים בַּחוֹמָה וְגוֹ׳. אוֹתָם שֶׁהָיוּ בּוֹנִין וְאוֹתָן שֶׁהָיוּ עוֹמְסִים וְנוֹשְׂאִים הַמַּשָּׂאוֹת, בְּיָד אַחַת הָיוּ עוֹשִׂים מְלַאכְתָּן וּבְיָד אַחַת הָיוּ נוֹשְׂאִים כְּלֵי זַיִן:",1,0],[4,11,"הַשֶּׁלַח. כְּלִי קְרָב, כְּמוֹ ״מֵעֲבוֹר בַּשֶּׁלַח״ (איוב לג:יח). וְכֵן חִבְּרוֹ מְנַחֵם:",2,0],[4,12,"וְהַבּוֹנִים. כֵּיצַד הֵם בּוֹנִים? שֶׁהָיוּ כֻלָּם חֲגוּרִים אִישׁ חַרְבּוֹ עַל מָתְנָיו וּבוֹנִים:",1,0],[4,12,"אֶצְלִי. הוּא הָיָה תָּדִיר אֶצְלִי:",2,0],[4,13,"הַרְבֵּה. הִיא גְּדוֹלָה:",1,0],[4,14,"יִלָּחֶם לָנוּ. יִלָּחֵם בַּעֲדֵינוּ:",1,0],[4,16,"אִישׁ וְנַעֲרוֹ. כָּל אֶחָד וְאֶחָד מִן הַבּוֹנִים וּבָחוּר אֶחָד עִמּוֹ:",1,0],[4,16,"יָלִינוּ בְּתוֹךְ יְרוּשָׁלִָם. וְהַלַּיְלָה הָיָה לָהֶם לְמִשְׁמָר וְהַיּוֹם עוֹשִׂים מְלָאכָה, נִמְצָא שֶׁלֹּא הָיוּ יְשֵׁנִים כְּלוּם:",2,0],[4,17,"אֵין אֲנַחְנוּ פּוֹשְׁטִים בְּגָדֵינוּ. תָּמִיד הָיִינוּ זְרִיזִים בַּמִּשְׁמָר:",1,0],[4,17,"אִישׁ שִׁלְחוֹ הַמָּיִם. מֵיסַב עַל אֵין שֶׁלְּמַעְלָה, כְּמוֹ (שמואל א ב:ג) ״יֵצֵא עָתָק מִפִּיכֶם״. אֵין אִישׁ מִמֶּנּוּ פּוֹשֵׁט בְּגָדָיו לִשְׁכַּב אוֹ לִרְחֹץ אוֹתָם בַּמַּיִם. וְכֶפֶל לָשׁוֹן הוּא עַל אֵין אֲנַחְנוּ פוֹשְׁטִים:",2,0],[4,17,"שִׁלְחוֹ. הַפְּשָׁט כְּמוֹ ״וּפָשַׁט אֶת בְּגָדָיו״ (ויקרא ו:ד), דִּמְתֻּרְגָּם ״וְשָׁלַח״:",3,0],[5,1,"וַתְּהִי צַעֲקַת הָעָם וּנְשֵׁיהֶם גְּדוֹלָה. דַּלַּת הָעָם הָעֲנִיִּים הָיוּ צוֹעֲקִים מְאֹד:",1,0],[5,1,"אֶל אֲחֵיהֶם הַיְּהוּדִים. בִּשְׁבִיל אֲחֵיהֶם הַיְּהוּדִים הָעֲשִׁירִים:",2,0],[5,2,"וְיֵשׁ אֲשֶׁר אוֹמְרִים. נוֹתֵן טַעַם לִדְבָרָיו לָמָּה הָיוּ צוֹעֲקִים: יֵשׁ מֵהֶם מִדַּלַּת הָעָם שֶׁהָיוּ אוֹמְרִים אֲנַחְנוּ רַבִּים עִם בָּנֵינוּ וּבְנוֹתֵינוּ וְנִקְחָה דָגָן וְעַתָּה יֵשׁ לָנוּ לִמְכֹּר בָּנֵינוּ וּבְנוֹתֵינוּ לִיקַּח מֵהֶם דָגָן לְמַעַן נִחְיֶה. כָּךְ הָיוּ צוֹעֲקִים עַל הַיְּהוּדִים הָעֲשִׁירִים שֶׁלֹּא הָיוּ רוֹצִים לְפַרְנְסָם:",1,0],[5,3,"וְיֵשׁ אֲשֶׁר אוֹמְרִים שְׂדוֹתֵינוּ וְגוֹ׳. וְיֵשׁ מֵהֶם בָּעֲנִיִּים שֶׁהָיוּ מִתְאוֹנְנִים וְאוֹמְרִים: שָׂדוֹת וּכְרָמִים וּבָתִּים נָתַן לַאֲחֵרִים בְּעֵרָבוֹן וּמַשְׁכּוֹן לִיקַּח דָּגָן לִמְזוֹנוֹתֵינוּ:",1,0],[5,3,"בָּרָעָב. אַחֲרֵי שֶׁאֵין מְוַתְּרִים לָנוּ הָעֲשִׁירִים מִנִּכְסֵיהֶם לְפַרְנָסָתֵנוּ:",2,0],[5,4,"וְיֵשׁ אֲשֶׁר אוֹמְרִים לָוִינוּ כֶסֶף. וְיֵשׁ מֵהֶם אֲשֶׁר אוֹמְרִים: כְּבָר לָוִינוּ כֶסֶף מֵאֲחֵרִים עַל שְׂדוֹתֵינוּ וּכְרָמֵינוּ לִפְרֹעַ מַס הַמֶּלֶךְ, וּמֵעַכְשָׁיו אֵין לָנוּ כְּלוּם לְצֹרֶךְ פַּרְנָסָתֵנוּ:",1,0],[5,4,"לְמִדַּת הַמֶּלֶךְ. לְמַס הַמֶּלֶךְ, כְּמוֹ ״מִנְדָּה בְלוֹ וַהֲלָךְ״ (עזרא ד:יג):",2,0],[5,5,"וְעַתָּה כִּבְשַׂר אַחֵינוּ בְשָׂרֵנוּ. וְעַכְשָׁיו אָנוּ חֲשׁוּבִים וּמְיֻחָסִים כְּאַחֵינוּ שֶׁהֵם עֲשִׁירִים:",1,0],[5,5,"כִּבְנֵיהֶם בָּנֵינוּ. כִּבְנֵיהֶם שֶׁהֵם חֲשׁוּבִים וּמְיֻחָסִים, כְּמוֹ כֵן מְיֻחָסִים בָּנֵינוּ:",2,0],[5,5,"וְהִנֵּה אֲנַחְנוּ כֹבְשִׁים. וְעַתָּה יֵשׁ לָנוּ לִהְיוֹת כֹּבְשִׁים וְנוֹתְנִים בָּנֵינוּ וּבְנוֹתֵינוּ לַאֲחֵרִים עַל עֵסֶק מְזוֹנוֹתֵינוּ:",3,0],[5,5,"וְיֵשׁ מִבְּנוֹתֵינוּ נִכְבָּשׁוֹת. וּכְבָר יֵשׁ קְצָת מִבְּנוֹתֵינוּ שֶׁהֵן נִכְבָּשׁוֹת לַאֲחֵרִים לְעַבְדוּת:",4,0],[5,5,"וְאֵין לְאֵל יָדֵינוּ. וְאֵין כֹּחַ בְּיָדֵינוּ לִפְדּוֹתָם:",5,0],[5,5,"וּשְׂדוֹתֵינוּ וּכְרָמֵינוּ לַאֲחֵרִים. אַף שָׂדוֹת וּכְרָמִים מָסַרְנוּ בְּיַד אֲחֵרִים לְפַרְנָסָתֵנוּ, וּמַה נֹּאכַל מֵעַתָּה, כִּי אֵין לָנוּ בַּמֶּה לְהִתְפַּרְנֵס:",6,0],[5,7,"וַיִּמָּלֵךְ. וַיִּוָּעֵץ לִבִּי בְּעַצְמִי:",1,0],[5,7,"וָאָרִיבָה. נִתְוַכַּחְתִּי עִם הַחוֹרִים וְהַסְּגָנִים שֶׁהֵם הָעֲשִׁירִים:",2,0],[5,7,"מַשָּׁא אִישׁ בְּאָחִיו אַתֶּם. נוֹשִׁים מַדּוּעַ אַתֶּם כָּךְ עוֹשִׂים? הָיָה לָכֶם לְפַרְנֵס הָעֲנִיִּים הַלָּלוּ, וְאַתֶּם מַלְוִים לָהֶם מָמוֹן לִכְבּוֹשׁ בְּנֵיהֶם וּבְנוֹתֵיהֶם וּשְׂדוֹתֵיהֶם וְכַרְמֵיהֶם וּבָתֵּיהֶם:",3,0],[5,7,"וָאֶתֵּן עֲלֵיהֶם קְהִלָּה גְדוֹלָה. הִקְהַלְתִּי וְאָסַפְתִּי עֲלֵיהֶם קְהִלָּה גְדוֹלָה לִצְעוֹק עֲלֵיהֶם, כְּדֵי לְבַיְּשָׁם:",4,0],[5,8,"וָאֹמְרָה לָהֶם. וְכֵן אָמַרְתִּי לָהֶם: אֲנַחְנוּ קָנִינוּ כְּבָר אֶת אַחֵינוּ הַיְּהוּדִים אֲשֶׁר בַּשִּׁבְיָה מִיַּד הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁהָיוּ נִמְכָּרִים לָהֶם:",1,0],[5,8,"כְּדֵי בָּנוּ. בְּאוֹתוֹ דֵּי מָמוֹן שֶׁבְּיָדֵינוּ:",2,0],[5,8,"וְגַם אַתֶּם. וְאַף אַתֶּם תִּמְכְּרוּ לְעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אֶת אֲחֵיכֶם הַנִּכְבָּשִׁים תַּחַת יְדֵיכֶם לַעֲבָדִים:",3,0],[5,8,"וְנִמְכְּרוּ לָנוּ. וְהַמַּעֲשֶׂה יָבֹא לִידֵי כָּךְ שֶׁיִּהְיוּ מְכוּרִים לָנוּ מִיַּד הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. (אִם כֵּן לָמָּה תִּמְכְּרוּ אוֹתָם כֵּיוָן שֶׁמֻּכְרָחִים אֲנַחְנוּ לִפְדּוֹתָם. כן הוא בספרים אחרים):",4,0],[5,8,"וַיַּחֲרִישׁוּ. שָׁתְקוּ וְנִתְבַּיְּשׁוּ וְלֹא יָדְעוּ מַה לְּהָשִׁיב:",5,0],[5,9,"לֹא טוֹב הַדָּבָר. רַע הַדָּבָר בִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא:",1,0],[5,9,"מֵחֶרְפַּת. מִפְּנֵי חֶרְפּוֹת הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁהֵם אוֹיְבֵינוּ:",2,0],[5,10,"וְגַם אֲנִי אַחַי וּנְעָרַי. אַף אֲנִי וַחֲבֵרַי נוֹשִׁים בָּהֶם מָמוֹן, וַאֲנַחְנוּ נַעֲזֹב וְנִמְחֹל לָהֶם כָּל הַהַלְוָאוֹת הַלָּלוּ:",1,0],[5,10,"נוֹשִׁים. כְּמוֹ (מלכים ב ד:א) ״וְהַנֹּשֶׁה בָּא לָקַחַת״:",2,0],[5,11,"הָשִׁיבוּ נָא. וְאַף אַתֶּם תַּעֲשׂוּ כָּמוֹנִי לִמְחֹל לָהֶם כָּל חוֹבוֹתֵיהֶם:",1,0],[5,11,"וּמְאַת הַכֶּסֶף. וְרוֹב הַכֶּסֶף שֶׁהֵם חַיָּבִים לָכֶם עִם הַדָּגָן וְתִירוֹשׁ וְגוֹ׳:",2,0],[5,12,"וַיֹּאמְרוּ נָשִׁיב. וְהֵם אָמְרוּ לְהָשִׁיב וְלִמְחֹל הַכֹּל:",1,0],[5,12,"לַעֲשׂוֹת כַּדָּבָר הַזֶּה. שֶׁיְּהוּ מוֹחֲלִים גַּם הֵם:",2,0],[5,13,"גַּם חָצְנִי נָעַרְתִּי. אַף אֲנִי בְּגָדַי נִעַרְתִּי. חָצְנִי כְּמוֹ ״וְהֵבִיאוּ בָנַיִךְ בְּחֹצֶן״ (ישעיה מט:כב):",1,0],[5,13,"נָעַרְתִּי. אֵישְׁקוֹלִיי״ר בְּלַעַ״ז, כְּמוֹ ״הִתְנַעֲרִי מֵעָפָר״ (ישעיה נב:ב):",2,0],[5,13,"כָּכָה יְנַעֵר. כָּכָה יְנַעֵר הַקָּדוֹשׁ בָּרוּךְ הוּא מִן הָעוֹלָם וּמִנִּכְסֵיהֶם כָּל אוֹתָם שֶׁלֹּא יִהְיוּ מוֹחֲלִין חוֹבוֹתֵיהֶם:",3,0],[5,13,"נָעוּר וָרֵק. בְּלֹא נְכָסִים:",4,0],[5,14,"אֲשֶׁר צִוָּה אוֹתִי. הַמֶּלֶךְ:",1,0],[5,14,"פֶּחָם. כְּמוֹ פֶּחָה שָׁלְטָן, דּוּגְמַת רֵיקָם שֶׁהוּא כְּמוֹ רֵֵיקָה:",2,0],[5,14,"מִשְּׁנַת עֶשְׂרִים. לְמֶלֶךְ דָּרְיָוֶשׁ, כִּי אָז עָלָה מִבָּבֶל, שֶׁנֶּאֱמַר (נחמיה ב:א) ״וַיְהִי בְחֹדֶשׁ נִיסָן שְׁנַת עֶשְׂרִים וְגוֹ׳״:",3,0],[5,14,"שָׁנִים שְׁתֵּים עֶשְׂרֵה. שֶׁהֵם שְׁתֵּים עֶשְׂרֵה שָׁנָה:",4,0],[5,14,"אֲנִי וְאַחַי. אֲנִי וַחֲבֵרַי אֲשֶׁר בָּאוּ עִמִּי:",5,0],[5,14,"לֶחֶם הַפֶּחָה לֹא אָכַלְתִּי. לֶחֶם שֶׁהוּא רָאוּי לְמַאֲכַל הַפֶּחָה, שֶׁהָעָם נוֹתְנִין אוֹתוֹ אֶל הַפֶּחָה מִן הַמַּס:",6,0],[5,15,"הִכְבִּידוּ עַל הָעָם. הִכְבִּידוּ מַס עַל הָעָם:",1,0],[5,15,"וַיִּקְחוּ. וְהָיוּ לוֹקְחִים מֵהֶם בִּשְׁבִיל הַמַּס לֶחֶם וָיַיִן אַחַר נְתִינַת אַרְבָּעִים שְׁקָלִים שֶׁל כֶּסֶף, וְכָךְ הָיוּ רְגִילִים בְּכָל שָׁנָה:",2,0],[5,15,"גַּם נַעֲרֵיהֶם. שֶׁל פַּחוֹת:",3,0],[5,16,"הַחוֹמָה. חוֹמַת הָעִיר:",1,0],[5,16,"הֶחֱזַקְתִּי. הִתְעַסַּקְתִּי לַעֲסוֹק בָּהּ תָּדִיר:",2,0],[5,16,"וְשָׂדֶה לֹא קָנִינוּ. וּבַשָּׂדוֹת שֶׁל הַיְּהוּדִים שֶׁהָיוּ בּוֹנִים הַחוֹמָה לֹא קָנִינוּ אֲנִי וּבְנֵי סִיעָתִי עַל עֵסֶק דָּחְקָם, שֶׁהָיוּ עוֹסְקִין בְּבִנְיַן הַחוֹמָה, אֲבָל הָיִיתִי נוֹתֵן לָהֶם מָמוֹן כְּדֵי לִבְנוֹת הַבִּנְיָן:",3,0],[5,16,"עַל הַמְּלָאכָה. לִבְנוֹת תָּדִיר:",4,0],[5,17,"מֵאָה וַחֲמִשִּׁים אִישׁ. הָיוּ אוֹכְלִים עַל שֻׁלְחָנִי, לְבַד הַגֵּרִים הַבָּאִים אֵלֵינוּ מִן הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, שֶׁאַף הֵם הָיוּ אוֹכְלִים עַל שֻׁלְחָנִי:",1,0],[5,18,"וַאֲשֶׁר הָיָה נַעֲשֶׂה. וּבְכָל יוֹם וָיוֹם הָיוּ אוֹכְלִים עַל שֻׁלְחָנִי שׁוֹר אֶחָד וְשֵׁשׁ צֹאן וְצִפֳּרִים הַרְבֵּה:",1,0],[5,18,"בְּרוּרוֹת. פִּתְרוֹנוֹ לְפִי עִנְיָנוֹ: שֵׁשׁ צֹאן עֲשׂוּיוֹת, כְּעִנְיָן שֶׁנֶּאֱמַר ״חָמֵשׁ צֹאן עֲשׂוּיוֹת״ (שמואל א כה:יח):",2,0],[5,18,"נַעֲשׂוּ לִי. לְשׁוֹן תִּקּוּן, כְּמוֹ ״וּבֶן הַבָּקָר אֲשֶׁר עָשָׂה״ (בראשית יח:ח):",3,0],[5,18,"וּבֵין עֲשֶׂרֶת יָמִים. וּבְכָל יוֹם וָיוֹם הָיוּ שׁוֹתִים יַיִן הַרְבֵּה כְּדֵי שִׁיעוּר סִפּוּק שֶׁל עֲשֶׂרֶת יָמִים:",4,0],[5,18,"וְעִם זֶה. וּבִשְׁבִיל כָּל מַעֲשֶׂה זֶה שֶׁהָיִיתִי מוֹצִיא הוֹצָאוֹת כָּל כָּךְ:",5,0],[5,18,"לֶחֶם. שֶׁל מַס הָרָאוּי לַפֶּחָה לֹא בִקַּשְׁתִּי וְלֹא שָׁאַלְתִּי מִן הָעָם, שֶׁהֲרֵי כָּבְדָה וְחָזָקָה עֲבוֹדַת בִּנְיַן הַחוֹמָה עֲלֵיהֶם:",6,0],[6,1,"וְלֹא נוֹתַר בָּהּ. בְּחוֹמַת הָעִיר:",1,0],[6,1,"דְּלָתוֹת לֹא הֶעֱמַדְתִּי. שֶׁלֹּא נַעֲשׂוּ דְלָתוֹת בְּשַׁעֲרֵי הָעִיר:",2,0],[6,2,"בַּכְּפִירִים. שֵׁם מָקוֹם הוּא:",1,0],[6,2,"בְּבִקְעַת אוֹנוֹ. כָּךְ שֵׁם הַבִּקְעָה:",2,0],[6,2,"וְהֵמָּה חוֹשְׁבִים. הֵבַנְתִּי מֵהֶם שֶׁהָיוּ חוֹשְׁבִים עָלַי לְהָרְגֵנִי שָׁם:",3,0],[6,3,"מְלָאכָה גְדוֹלָה אֲנִי עֹשֶׂה. מִבִּנְיָנֵי (הָעִיר. ספרים אחרים) הֶעָפָר:",1,0],[6,3,"לָמָּה תִשְׁבַּת. לָמָּה תִּהְיֶה הַמְּלָאכָה בְּטֵלָה?",2,0],[6,3,"כַּאֲשֶׁר אַרְפֶּהָ. יָדִי מִן הַבִּנְיָן:",3,0],[6,3,"וְיָרַדְתִּי אֲלֵיכֶם. לְדַבֵּר וּלְהִוָּעֵד אֲלֵיכֶם:",4,0],[6,5,"אֶת נַעֲרוֹ. עַל יְדֵי נַעֲרוֹ:",1,0],[6,5,"וְאִגֶּרֶת פְּתוּחָה בְּיָדוֹ. כָּתַב אִגֶּרֶת שָׁלַח לִי עַל יָדוֹ:",2,0],[6,6,"כָּתוּב בָּהּ. בְּאוֹתָהּ אִגֶּרֶת:",1,0],[6,6,"בַּגּוֹיִם נִשְׁמָע. שֶׁנּוֹדַע לְכָל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁאַתָּה וְכָל הַיְּהוּדִים חוֹשְׁבִים לִמְרוֹד:",2,0],[6,6,"וְגַשְׁמוּ אוֹמֵר. גַּשְׁמוּ הוּא גֶּשֶׁם הָעֲרָבִי (נחמיה ב:יט), וּפִתְרוֹנוֹ כְּאָדָם שֶׁאוֹמֵר לַחֲבֵירוֹ כָּךְ הוּא הַדָּבָר וּפְלוֹנִי אוֹמֵר:",3,0],[6,6,"כַּדְּבָרִים הָאֵלֶּה. מוּסָב עַל כָּתוּב בָּהּ; וּמִקְרָא מְסֹרָס הוּא, וַהֲרֵי הוּא כְּאִלּוּ נֶאֱמַר: כָּתוּב בָּהּ כַּדְּבָרִים הָאֵלֶּה בַּגּוֹיִם נִשְׁמָע וְגוֹ׳:",4,0],[6,7,"וְגַם נְבִיאִים וְגוֹ׳. עַד וְנִוָּעֲצָה יַחְדָּו הָיָה כָתוּב בָּאִגֶּרֶת:",1,0],[6,7,"נְבִיאִים. בַּעֲלֵי לָשׁוֹן, כְּמוֹ ״בּוֹרֵא נִיב שְׂפָתָיִם״ (ישעיה נז:יט):",2,0],[6,7,"לֵאמֹר. שֶׁאוֹמְרִים: יֵשׁ מֶלֶךְ בִּיהוּדָה:",3,0],[6,7,"וְעַתָּה יִשָּׁמַע לַמֶּלֶךְ. אַחֲרֵי שֶׁנִּקְרֵאתָ מֶלֶךְ יִשָּׁמַע לַמֶּלֶךְ כַּדְּבָרִים הָאֵלֶּה:",4,0],[6,8,"כִּי מִלִּבְּךָ. הֲרֵי כִּי בִּמְקוֹם אֶלָּא:",1,0],[6,8,"בּוֹדָם. קוֹנְטְרַבְנְטַאלְ״שׁ בְּלַעַ״ז, כְּמוֹ אֲשֶׁר בָּדָה מִלִּבּוֹ:",2,0],[6,9,"כִּי כֻלָּם. כִּי כָּל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:",1,0],[6,9,"מְיָרְאִים אוֹתָנוּ. מִתְיָרְאִים מִמֶּנּוּ, וְכָךְ הֵם אוֹמְרִים: יִרְפּוּ יְדֵיהֶם וְגוֹ׳:",2,0],[6,9,"וְעַתָּה חַזֵּק אֶת יָדָי. לְסַיְּעֵנִי בְּבִנְיַן הַחוֹמָה:",3,0],[6,10,"וְהוּא עָצוּר. שֶׁמְּצָאוֹ בְּבֵיתוֹ:",1,0],[6,10,"וַיֹּאמֶר נִוָּעֵד. אוֹתוֹ שְׁמַעְיָה הָיָה נְבִיא שֶׁקֶר, וְקִבֵּל שֹׁחַד מִן סַנְבַלַּט וַחֲבֵרָיו לְהַפְחִיד אֶת נְחֶמְיָה, כְּדֵי לְבַטֵּל אֶת הַמְּלָאכָה:",2,0],[6,10,"כִּי בָאִים לְהָרְגֶךָ. שֶׁהֲרֵי יָבוֹאוּ לְהָרְגְךָ סַנְבַלַּט וַחֲבֵרָיו:",3,0],[6,10,"וְלַיְלָה בָּאִים. וְעַל כֵּן הִזְהִירוּ לִיכָּנֵס בַּהֵיכָל וְלִסְגֹּר הַדְּלָתוֹת עָלָיו, שֶׁעֲדַיִן לֹא נַעֲשׂוּ דַלְתוֹת שַׁעֲרֵי הָעִיר, כְּמָה שֶׁנֶּאֱמַר בִּתְחִלַּת הַפָּרָשָׁה: ״גַּם עַד הָעֵת הַהִיא דְּלָתוֹת לֹא הֶעֱמַדְתִּי בַשְּׁעָרִים״ (נחמיה ו:א):",4,0],[6,11,"הַאִישׁ כָּמוֹנִי יִבְרָח. בִּתְמִיהָּ אִם אִישׁ כָּמוֹנִי יִבְרָח לִיכָּנֵס בַּהֵיכָל:",1,0],[6,11,"לֹא אָבוֹא. לֹא אֶכָּנֵס שָׁם מִפְּנֵי פַּחַד הַמִּיתָה, וְלֹא אֶעֱבֹר עַל הַמִּצְוָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יָבוֹא וְיִכָּנֵס זָר בְּהֵיכָלוֹ:",2,0],[6,12,"וָאַכִּירָה. הִכַּרְתִּי בִּדְבָרָיו שֶׁלֹּא שְׁלָחוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדָבָר זֶה שֶׁאֶעֱבֹר עֲבֵרָה מִפְּנֵי פַּחַד הַמִּיתָה:",1,0],[6,12,"כִּי הַנְּבוּאָה דִּבֶּר עָלַי. שֶׁהֲרֵי הוּא דִּבֵּר הַדְּבָרִים הַלָּלוּ עָלַי בְּשֵׁם נְבוּאָה:",2,0],[6,12,"שְׂכָרוֹ. כָּל אֶחָד וְאֶחָד מֵהֶם שְׂכָרוֹ, וְנָתְנוּ לוֹ שָׂכָר לְהַפְחִידֵנִי וּלְבַטֵּל בְּבִנְיַן הַחוֹמָה:",3,0],[6,13,"לְמַעַן שָׂכוּר הוּא. אָמַר לִי הַדְּבָרִים הַלָּלוּ:",1,0],[6,13,"לְמַעַן אִירָא. כְּדֵי שֶׁאֶתְיָרֵא מֵהֶם לִהְיוֹת עוֹשֶׂה כֵּן לִיכָּנֵס בַּהֵיכָל וְלִהְיוֹת חוֹטֵא:",2,0],[6,13,"וְהָיָה לָהֶם לְשֵׁם רָע. לְמַעַן שֶׁיִּהְיֶה לָהֶם לְשֵׁם רָע, לְחָרְפֵנִי בַּעֲבֵרָה זוֹ:",3,0],[6,14,"וְגַם לְנוֹעַדְיָה הַנְּבִיאָה. הִיא וּשְׁאָר נְבִיאֵי הַשֶּׁקֶר קִבְּלוּ שָׂכָר מִסַּנְבַלַּט וַחֲבֵרָיו כְּדֵי לְהַפְחִידֵנִי בִּנְבוּאַת שִׁקְרֵיהֶם:",1,0],[6,15,"בְּעֶשְׂרִים וַחֲמִשָּׁה. יָמִים לְחֹדֶשׁ אֱלוּל בִּשְׁנַת עֶשְׂרִים לְדָרְיָוֶשׁ הַמֶּלֶךְ, שֶׁבִּשְׁנַת עֶשְׂרִים לְדָרְיָוֶשׁ עָלָה נְחֶמְיָה מִבָּבֶל וּבְאוֹתָהּ שָׁנָה בָּנָה חָרְבוֹת יְרוּשָׁלָיִם:",1,0],[6,15,"לַחֲמִשִּׁים וּשְׁנַיִם יוֹם. סוֹף חֲמִשִּׁים וּשְׁתַּיִם יוֹם מִיּוֹם שֶׁהִתְחִילוּ לִבְנוֹתוֹ נִגְמַר בִּנְיַן הַחוֹמָה:",2,0],[6,16,"וַיְהִי כַּאֲשֶׁר שָׁמְעוּ כָּל אוֹיְבֵינוּ. דָּבָר זֶה שֶׁנִּשְׁלַם בִּנְיַן הַחוֹמָה:",1,0],[6,16,"וַיִּרְאוּ כָל הַגּוֹיִם. וְכַאֲשֶׁר רָאוּ כָל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁנִּגְמַר בִּנְיַן חוֹמַת הָעִיר:",2,0],[6,16,"וַיִּפְּלוּ מְאֹד בְּעֵינֵיהֶם. נָפְלוּ הֵם עַצְמָם בְּעֵינֵיהֶם שֶׁהָיוּ מוֹאֲסִים בְּעַצְמָם, כִּי נָפַל פַּחַד הַיְּהוּדִים עֲלֵיהֶם:",3,0],[6,17,"חוֹרֵי יְהוּדָה. שָׂרֵי יְהוּדָה:",1,0],[6,17,"עַל טוֹבִיָּה. אֶל טוֹבִיָּה. יִשְׂרָאֵל רָשָׁע הָיָה:",2,0],[6,17,"וַאֲשֶׁר לְטוֹבִיָּה. וְאִגֶּרֶת אֲשֶׁר לְטוֹבִיָּה:",3,0],[6,18,"כִּי רַבִּים בִּיהוּדָה. שֶׁהָיוּ שָׂרִים רַבִּים בִּיהוּדָה אֲשֶׁר הָיוּ לוֹ לְטוֹבִיָּה בַּעֲלֵי בְּרִית וּשְׁבוּעָה:",1,0],[6,18,"כִּי חָתָן הוּא. אוֹתוֹ טוֹבִיָּה לִשְׁכַנְיָה:",2,0],[6,18,"וִיהוֹחָנָן בְּנוֹ. שֶׁל טוֹבִיָּה:",3,0],[6,18,"בַּת מְשֻׁלָּם. אוֹתוֹ מְשֻׁלָּם שַׂר וְגָדוֹל הָיָה:",4,0],[6,19,"גַּם טוֹבוֹתָיו. שֶׁל טוֹבִיָּה הָיוּ מְסַפְּרִים לְפָנַי אוֹתָן בַּעֲלֵי שְׁבוּעָתוֹ וּקְרוֹבָיו:",1,0],[6,19,"טוֹבוֹתָיו. שֶׁשְׁפְּרוֹאוּצְ״שׁ בְּלַעַ״ז:",2,0],[6,19,"הָיוּ מוֹצִיאִים לוֹ. לְהַגִּיד לוֹ לְטוֹבִיָּה:",3,0],[6,19,"אִגְּרוֹת שָׁלַח טוֹבִיָּה. אִגְּרוֹת הָיָה שׁוֹלֵחַ תָּדִיר לְהַפְחִידֵנִי, שֶׁלֹּא לִבְנוֹת בִּנְיַן הַחוֹמָה:",4,0],[7,1,"וַיִּפָּקְדוּ. עַתָּה נַעֲשׂוּ הַלְוִיִּם פְּקוּדִים עַל פְּקִידוּתָן, לִהְיוֹתָן שׁוֹעֲרִים וּמְשׁוֹרְרִים מִן הַלְוִיִּם בְּבֵית הַמִּקְדָּשׁ:",1,0],[7,2,"עַל יְרוּשָׁלִָם. לִשְׁמֹר שַׁעֲרֵי יְרוּשָׁלָיִם:",1,0],[7,2,"מֵרַבִּים. מִיָּמִים רַבִּים:",2,0],[7,3,"עַד חֹם הַשֶּׁמֶשׁ. עַד חֲצִי הַיּוֹם, שֶׁהָיָה הַיּוֹם גָּדוֹל:",1,0],[7,3,"וְעַד הֵם עוֹמְדִים. וּבְעוֹד שֶׁהַשְּׁעָרִים פְּתוּחִים יִהְיוּ עוֹמְדִים, שֶׁלֹּא יָזוּזוּ עַד יָגִיפוּ וְיִסְגְּרוּ הַדְּלָתוֹת, וְהָרוֹצֶה לָצֵאת יֵצֵא מִן הָעִיר וְהָרוֹצֶה לִיכָּנֵס יָבֹא וְיִכָּנֵס. כָּל כָּךְ הָיוּ עוֹשִׂים מִפְּנֵי הָאוֹיְבִים:",2,0],[7,3,"וֶאֱחֹזוּ. יֹאחֲזוּ הַדְּלָתוֹת לְסָגְרָם:",3,0],[7,3,"מִשְׁמְרוֹת יוֹשְׁבֵי יְרוּשָׁלַ͏ִם. מִיּוֹשְׁבֵי יְרוּשָׁלִַם הֶעֱמִידוּ מִשְׁמָרוֹת, גִּיטְ״שׁ בְּלַעַ״ז:",4,0],[7,4,"רַחֲבַת יָדַיִם. רְחַבַת מָקוֹם וּגְדוֹלָה:",1,0],[7,5,"לְהִתְיַחֵשׂ. לַחֲקוֹר יִחוּסָן:",1,0],[7,5,"הָעוֹלִים בָּרִאשׁוֹנָה. מֵאוֹתָן הַיְּהוּדִים הָעוֹלִים עִם עֶזְרָא בָּרִאשׁוֹנָה:",2,0],[7,5,"וָאֶמְצָא כָתוּב בּוֹ. כָּל אֵלֶּה הַדְּבָרִים הָיוּ כְתוּבִים בְּאוֹתָהּ אִגֶּרֶת:",3,0],[7,6,"אֵלֶּה בְּנֵי הַמְּדִינָה וְגוֹ׳. עַד ״וְהַגּוֹרָלוֹת הִפַּלְנוּ עַל קָרְבַּן הָעֵצִים״ (נחמיה י:לה):",1,0],[7,6,"וְלִיהוּדָה. לִמְדִינַת יְהוּדָה׃",2,0],[7,6,"אִישׁ לְעִירוֹ. כָּל אֶחָד לְעִירוֹ:",3,0],[7,7,"הַבָּאִים עִם זְרֻבָּבֶל. אֲשֶׁר בָּאוּ מִשְּׁבִי הַגּוֹלָה עִם זְרֻבָּבֶל:",1,0],[7,7,"יֵשׁוּעַ. הוּא יְהוֹשֻׁעַ בֶּן יְהוֹצָדָק הַכֹּהֵן הַגָּדוֹל (חגי א:א). חֶשְׁבּוֹנוֹת הַלָּלוּ פְּעָמִים הֵם מְכֻוָּנִים עִם חֶשְׁבּוֹנוֹת שֶׁל מַעְלָה, פְּעָמִים יֵשׁ שֶׁאֵינָם מְכֻוָּנִים זֶה כְּנֶגֶד זֶה; וְלֹא דִקְדֵּק הַמִּקְרָא בַּחֶשְׁבּוֹנוֹת כָּל כָּךְ, אֲבָל הַכְּלָל שָׁוֶה (עַיֵּן בְּעֶזְרָא סִימָן ב פ״ב וְצָרִיךְ עִיּוּן יסוד ושרש העבודה) לְכָאן וּלְכָאן, שֶׁנֶּאֱמַר ״כָּל הַקָּהָל כְּאֶחָד וְגוֹ׳״ (נחמיה ז:סו). וְעַל זֶה הַכְּלָל סָמַךְ כּוֹתֵב הַסֵּפֶר, וְלֹא דִקְדֵּק בְּחֶשְׁבּוֹן הַפְּרָטִיּוֹת כָּל כָּךְ, וְהַכֹּל מְפֹרָשׁ לְמַעְלָה:",2,0],[8,2,"בְּיוֹם אֶחָד לַחֹדֶשׁ הַשְּׁבִיעִי. הוּא יוֹם שֶׁל רֹאשׁ הַשָּׁנָה (ראש השנה א,א):",1,0],[8,3,"מִן הָאוֹר. שֶׁל תְּחִלַּת הַיּוֹם:",1,0],[8,3,"אֶל סֵפֶר הַתּוֹרָה. הָיוּ כָל הָעָם מַטִּים אָזְנֵיהֶם:",2,0],[8,4,"אֲשֶׁר עָשׂוּ לַדָּבָר. אוֹתוֹ מִגְדַּל עֵץ עָשׂוּ לְשֵׁם כָּךְ, לִקְרוֹת שָׁם עָלָיו סֵפֶר הַתּוֹרָה:",1,0],[8,5,"כִּי מֵעַל כָּל הָעָם הָיָה. וְעַל כֵּן רָאוּהוּ כֻּלָּם:",1,0],[8,5,"וּכְפִתְחוֹ עָמְדוּ כָל הָעָם. וְכַאֲשֶׁר פְּתָחוֹ לִקְרוֹת שָׁתְקוּ כָּל הָעָם׃",2,0],[8,5,"עָמְדוּ. לְשׁוֹן שְׁתִיקָה (שָׁתְקוּ), כְּמוֹ ״עָמְדוּ וְלֹא עָנוּ עוֹד״ (אִיּוֹב לב:טז):",3,0],[8,6,"בְּמֹעַל יְדֵיהֶם. בִּנְשִׂיאוּת יְדֵיהֶם, שֶׁנָּשְׂאוּ כַפֵּיהֶם לְמַעְלָה לְהוֹדוֹת לְהַקָּדוֹשׁ בָּרוּךְ הוּא, כְּעִנְיָן שֶׁנֶּאֱמַר: ״וַיִּפְרֹשׂ כַּפָּיו הַשָּׁמָיִם״ (מְלָכִים א ח:כב):",1,0],[8,7,"מְבִינִים אֶת הָעָם. שֶׁהָיוּ מְתַרְגְּמִין לָעָם דִּבְרֵי תוֹרָה:",1,0],[8,7,"עַל עָמְדָם. שֶׁהָיוּ עוֹמְדִים עַל רַגְלֵיהֶם:",2,0],[8,8,"וְשׂוּם שֵׂכֶל. וְשִׂימַת חָכְמָה, וְשׂוּם לְשׁוֹן פָּעוּל:",1,0],[8,9,"הַיּוֹם קָדוֹשׁ. כִּי יוֹם רֹאשׁ הַשָּׁנָה הוּא:",1,0],[8,9,"כִּי בוֹכִים כָּל הָעָם. מִפְּנֵי שֶׁלֹּא קִיְּמוּ הַתּוֹרָה כָּרָאוּי:",2,0],[8,10,"לְאֵין נָכוֹן לוֹ. לֶעָנִי שֶׁאֵין מְזֻמָּן לוֹ מַאֲכָלוֹ:",1,0],[8,11,"מַחְשִׁים. הָיוּ מַזְהִירִין לְכָל הָעָם לַחֲשׁוֹת, שֶׁלֹּא יִבְכּוּ עוֹד:",1,0],[8,11,"הַסּוּ. לְשׁוֹן שְׁתִיקָה, כְּמוֹ ״וַיַּהַס כָּלֵב״ (במדבר יג:ל):",2,0],[8,13,"וּבַיּוֹם הַשֵּׁנִי. שֶׁל רֹאשׁ הַשָּׁנָה:",1,0],[8,15,"וַאֲשֶׁר יַשְׁמִיעוּ. וְצִוּוּ אֲשֶׁר יַשְׁמִיעוּ קוֹל לָחוֹג אֶת חַג הַסֻּכּוֹת, וְכֵן נוֹהֵג הַמִּקְרָא לְדַבֵּר כָּעִנְיָן הַזֶּה, כְּמוֹ ״אֱמֹר לַנַּעַר וְיַעֲבֹר לְפָנֵינוּ״ (שמואל א ט:כז):",1,0],[8,15,"וַעֲלֵי הֲדַס. מְפֹרָשׁ בְּמַסֶּכֶת סֻכָּה (סוכה יב,א): זֶה הֲדַס שׁוֹטֶה, שֶׁאֵינוֹ רָאוּי לְלוּלָב כִּי אִם לַעֲשׂוֹת סֻכָּה:",2,0],[8,15,"וַעֲלֵי תְמָרִים. לְלוּלָב:",3,0],[8,15,"וַעֲלֵי עֵץ עָבֹת. זֶה הֲדַס הָרָאוּי לְלוּלָב, כַּמְּפֹרָשׁ בְּמַסֶּכֶת סֻכָּה (סוכה לב,ב):",4,0],[8,18,"יוֹם בְּיוֹם. בְּכָל יוֹם וָיוֹם:",1,0],[9,1,"וַאֲדָמָה עֲלֵיהֶם. הֶעֱלוּ עָפָר עַל רֹאשָׁם:",1,0],[9,2,"מִכָּל בְּנֵי נֵכָר. וּמִנְּשֵׁיהֶם שֶׁל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, כְּמוֹ שֶׁנֶּאֱמַר לְמַעְלָה (נחמיה יג):",1,0],[9,4,"עַל מַעֲלֵה הַלְוִיִּם. מַעֲלוֹת הָיוּ שָׁם שֶׁהַלְוִיִּם עוֹמְדִים שָׁם עֲלֵיהֶם בְּשָׁעָה שֶׁאָמְרוּ שִׁירָה:",1,0],[9,5,"מִן הָעוֹלָם וְעַד הָעוֹלָם. מִתְּחִלַּת הָעוֹלָם וְעַד תַּכְלִיתוֹ יְהִי בָּרוּךְ:",1,0],[9,5,"וִיבָרְכוּ שֵׁם כְּבוֹדֶךָ. עַכְשָׁיו דִּבְּרוּ הַלְוִיִּם כְּלַפֵּי שְׁכִינָה בִּתְפִלָּה: וִיבָרְכוּ שֵׁם כְּבוֹדֶךָ כִּי הוּא גָּדוֹל וּמְרוֹמָם עַל כָּל בְּרָכָה וּתְהִלָּה, כִּי כָל הַבְּרָכוֹת וּתְהִלּוֹת שֶׁלּוֹ הֵם. דָּבָר אַחֵר: וּמְרוֹמַם עַל כָּל בְּרָכָה וּתְהִלָּה שֶׁאֵין בְּרִיָּה יְכוֹלָה לְבָרְכוֹ וּלְהַלְּלוֹ כְּפִי גָדְלוֹ וְרוֹמְמוּתוֹ, שֶׁהוּא מְרוֹמָם וְנִשָּׂא יוֹתֵר מַה שֶּׁאֵין הַפֶּה יְכוֹלָה לְדַבֵּר:",2,0],[9,7,"וְשַׂמְתָּ. טַעֲמוֹ לְמַעְלָה בַּשִּׂי״ן, לְפִי שֶׁמַּשְׁמָעוּתוֹ בִּלְשׁוֹן עָבָר:",1,0],[9,8,"וְכָרוֹת עִמּוֹ. לְשׁוֹן פָּעוּל:",1,0],[9,10,"כִּי הֵזִידוּ. כִּי הִרְשִׁיעוּ עֲלֵיהֶם, כְּמוֹ ״כִּי בַדָּבָר אֲשֶׁר זָדוּ עֲלֵיהֶם״ (שמות יח:יא):",1,0],[9,10,"שֵׁם. רָצוֹן בְּלַעַ״ז:",2,0],[9,12,"יוֹמָם. בְּכָל יוֹם וָיוֹם:",1,0],[9,13,"וְדַבֵּר. כְּמוֹ וּלְדַבֵּר, כְּמוֹ שֶׁנֶּאֱמַר ״מִן הַשָּׁמַיִם הִשְׁמִיעֲךָ אֶת קוֹלוֹ לְיַסְּרֶךָּ״ (דברים ד:לו):",1,0],[9,15,"לִרְעָבָם. מִן רָעָב יֹאמַר לִרְעָבָם, כְּמוֹ מִן צָמָא לִצְמָאָם:",1,0],[9,15,"אֲשֶׁר נָשָׂאתָ אֶת יָדְךָ. בִּשְׁבוּעָה, כְּמוֹ ״אֲשֶׁר נָשָׂאתִי אֶת יָדִי לָתֵת אֹתָהּ״ (שמות ו:ח):",2,0],[9,17,"בְּמִרְיָם. בִּשְׁבִיל מְרִי שֶׁלָּהֶם:",1,0],[9,19,"בְּהַדֶּרֶךְ. כְּמוֹ בַּדֶּרֶךְ׃",1,0],[9,22,"לְפֵאָה. כְּמוֹ לִהְיוֹת לְצַד זָוִית אַחַת מֻחְלָקִים, בְּלִי לְהִתְעָרֵב עִם גּוֹיֵי הָאֲרָצוֹת:",1,0],[9,24,"וַתַּכְנַע. וְהִכְנַעְתָּ:",1,0],[9,27,"וְאַתָּה מִשָּׁמַיִם תִּשְׁמָע. הָיִיתָ שׁוֹמֵעַ:",1,0],[9,30,"וַתִּמְשֹׁךְ עֲלֵיהֶם. מָשַׁכְתָּ עֲלֵיהֶם רַחֲמִים, שֶׁלֹּא לְהַשְׁחִיתָם:",1,0],[9,33,"עַל כָּל הַבָּא. עַל כָּל מַעֲשֵׂה יִסּוּרֶיךָ הָרָעִים אֲשֶׁר בָּאוּ עָלֵינוּ:",1,0],[9,36,"הִנֵּה אֲנַחְנוּ עֲבָדִים עָלֶיהָ. שֶׁאֲנַחְנוּ מַעֲלִים מַס לְכָל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:",1,0],[9,37,"וּתְבוּאָתָהּ. שֶׁל אֶרֶץ יִשְׂרָאֵל:",1,0],[9,37,"מַרְבָּה. מַעֲדַנֵּי מַאֲכָלִים לְמַלְכֵי הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:",2,0],[9,37,"אֲשֶׁר נָתַתָּה עָלֵינוּ. שֶׁהֵם מוֹשְׁלִים בָּנוּ:",3,0],[10,1,"וּבְכָל זֹאת. וּבְכָל הָרָעָה הַזֹּאת הַבָּאָה עָלֵינוּ אֲנַחְנוּ כּוֹרְתִים אֲמָנָה לְהַקָּדוֹשׁ בָּרוּךְ הוּא, לְהַאֲמִין וְלִבְטוֹחַ בּוֹ:",1,0],[10,1,"וְכוֹתְבִים. וַאֲנַחְנוּ כּוֹתְבִים בַּסֵּפֶר לְקַבֵּל מַלְכוּתוֹ עָלֵינוּ, לְמַעַן תִּהְיֶה לָנוּ לְעֵדוּת:",2,0],[10,1,"וְעַל הֶחָתוּם. שֶׁרוֹב גְּדוֹלִים וַחֲשׁוּבִים שֶׁבָּנוּ חֲתוּמִים עַל סֵפֶר קַבָּלַת הַמִּצְוֹת לִהְיוֹת לָנוּ לְעֵדוּת:",3,0],[10,2,"וְעַל הַחֲתוּמִים. עַתָּה מוֹנֶה וְהוֹלֵךְ הַחֲתוּמִים בַּסֵּפֶר לְעֵדוּת קִבּוּל הַמִּצְוֹת:",1,0],[10,2,"נְחֶמְיָה הַתִּרְשָׁתָא. שֵׁם אֶחָד הוּא, וְזֶהוּ שֶׁפֵּרַשְׁתִּי (עזרא ב:סג) דְּהַתִּרְשָׁתָא הוּא נְחֶמְיָה. וְלָמָּה נִקְרָא שְׁמוֹ הַתִּרְשָׁתָא? שֶׁהִתִּירוּ לוֹ חֲכָמִים לִשְׁתּוֹת יֵין נֶסֶךְ, לְפִי שֶׁהָיָה מַשְׁקֶה לַמֶּלֶךְ:",2,0],[10,29,"וְכָל הַנִּבְדָּל. הֵם הַגֵּרִים שֶׁנִּבְדְּלוּ מִתּוֹרַת הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, לִהְיוֹת דְּבוּקִים וּמְחֻבָּרִים אֶל תּוֹרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְלִשְׁמֹר מִצְוֹתָיו:",1,0],[10,30,"עַל אֲחֵיהֶם. עִם אֲחֵיהֶם:",1,0],[10,30,"אַדִּירֵיהֶם. גְּדוֹלִים שֶׁבָּהֶם:",2,0],[10,32,"הַמִּקָּחוֹת. הַסְּחוֹרוֹת:",1,0],[10,32,"שֶׁבֶר. תְּבוּאָה, כְּמוֹ ״בַּשֶּׁבֶר אֲשֶׁר הֵם שֹׁבְרִים״ (בראשית מז:יד):",2,0],[10,32,"וּבְיוֹם קֹדֶשׁ. שֶׁל יוֹם טוֹב:",3,0],[10,32,"וְנִטֹּשׁ אֶת הַשָּׁנָה הַשְּׁבִיעִית. כְּעִנְיָן שֶׁנֶּאֱמַר: ״וְהַשְּׁבִיעִת תִּשְׁמְטֶנָּה וּנְטַשְׁתָּהּ״ (שמות כג:יא):",4,0],[10,32,"וּמַשָּׁא כָל יָד. הַשְׁמָטַת מִלְוֶה בַּשְּׁבִיעִית (דברים טו:ב):",5,0],[10,34,"וְכָל מְלֶאכֶת בֵּית אֱלֹהֵינוּ. לַעֲשׂוֹת מִן הַכֶּסֶף:",1,0],[10,35,"הִפַּלְנוּ. כַּמָּה יָבִיא כָּל אֶחָד:",1,0],[10,35,"קֻרְבַּן הָעֵצִים. תִּקְרֹבֶת שֶׁל עֲצֵי הַמַּעֲרָכָה לַמִּזְבֵּחַ:",2,0],[10,35,"לְבֵית אֲבוֹתֵינוּ. שֶׁהִיא בֵּית קְדֻשַּׁת אֲבוֹתֵינוּ:",3,0],[10,36,"וּבִכּוּרֵי כָּל פְּרִי כָּל עֵץ. בִּכּוּרֵי שֶׁל כָּל פְּרִי הָאִילָן הֵם מִדִּבְרֵי חֲכָמִים:",1,0],[10,38,"נָבִיא לַכֹּהֲנִים אֶל לִשְׁכוֹת. כִּי שָׁם הָיוּ רְגִילִים:",1,0],[10,38,"הַמְעַשְּׂרִים בְּכָל עָרֵי עֲבוֹדָתֵנוּ. שֶׁנּוֹטְלִים מַעַשְׂרוֹתֵיהֶם בְּכָל עָרֵי יִשְׂרָאֵל:",2,0],[10,39,"בַּעְשֵׂר. לְשׁוֹן בַּעְשׂוֹר:",1,0],[10,39,"אֶת מַעֲשַׂר הַמַּעֲשֵׂר. שֶׁהָיוּ הַלְוִיִּם מְעַשְּׂרִים מַעֲשֵׂר מִן הַמַּעֲשֵׂר וּמְבִיאִים אוֹתוֹ לַכֹּהֲנִים שֶׁלֹּא הָיוּ עוֹזְבִים אֶת בֵּית הַמִּקְדָּשׁ:",2,0],[11,1,"אֶחָד מִן הָעֲשָׂרָה. שֶׁבְּיִשְׂרָאֵל, לְמַעַן יֵשְׁבוּ בִּירוּשָׁלַיִם לִשְׁמֹר הָעִיר:",1,0],[11,1,"וְתֵשַׁע הַיָּדוֹת. תִּשְׁעָה חֲלָקִים שֶׁבְּיִשְׂרָאֵל:",2,0],[11,2,"הַמִּתְנַדְּבִים. אֲשֶׁר נָדְבָה רוּחָם אוֹתָם לִהְיוֹת יוֹשְׁבִים בִּירוּשָׁלַיִם לִשְׁמֹר הָעִיר מִן הָאוֹיְבִים:",1,0],[11,3,"וְאֵלֶּה רָאשֵׁי הַמְּדִינָה אֲשֶׁר יָשְׁבוּ בִּירוּשָׁלִָם. הוּא שֶׁנֶּאֱמַר בְּסָמוּךְ וּבִירוּשָׁלִַם יָשְׁבוּ בְּנֵי יְהוּדָה וְגוֹ׳:",1,0],[11,4,"מִבְּנֵי יְהוּדָה עֲתָיָה וְגוֹ׳. חוֹזֵר וּמְפָרֵשׁ מִבְּנֵי יְהוּדָה מִי וָמִי הָיוּ. וְכָל הַפָּרָשָׁה אֵינָהּ מוֹנָה כִּי אִם הַגְּדוֹלִים וְהַחֲשׁוּבִים שֶׁבָּהֶם:",1,0],[11,9,"פָּקִיד. מְמֻנֶּה:",1,0],[11,9,"מִשְׁנֶה. אַחַר (הַפָּקִיד):",2,0],[11,11,"נְגִד. מְמֻנֶּה:",1,0],[11,11,"נְגִיד בֵּית הָאֱלֹהִים. מְמֻנֶּה עַל בֵּית אֱלֹהִים:",2,0],[11,12,"וַאֲחֵיהֶם עֹשֵׂה הַמְּלָאכָה לַבָּיִת. וְחַבְרֵיהֶם שֶׁהָיוּ עוֹבְדִים עֲבוֹדַת הַבַּיִת וְקָרְבְּנוֹתָיו:",1,0],[11,13,"רָאשִׁים לְאָבוֹת. רָאשֵׁי בֵית אָב מִמִּשְׁפְּחוֹת הַכֹּהֲנִים:",1,0],[11,14,"וּפָקִיד עֲלֵיהֶם. מְמֻנֶּה עֲלֵיהֶם:",1,0],[11,16,"עַל הַמְּלָאכָה הַחִיצוֹנָה. אֲשֶׁר לַבַּיִת, כְּגוֹן בִּנְיָנֵי בֶדֶק הַבַּיִת וַעֲצֵי הַמַּעֲרָכָה שֶׁהָיוּ מְבִיאִים מִבַּחוּץ:",1,0],[11,17,"רֹאשׁ הַתְּחִלָּה יְהוֹדֶה לַתְּפִלָּה. הוּא הָיָה רֹאשׁ וּמְמֻנֶּה וְגָדוֹל לִפְתֹּחַ תְּחִלָּה לְהוֹדוֹת בַּתְּפִלָּה וּבִזְמִירוֹת שִׁירוֹתֵיהֶם שֶׁל לְוִיִּם. יְהוֹדֶה כְּמוֹ יוֹדֶה, וְהַהֵ״א נִכְנֶסֶת בַּתֵּיבָה שֶׁלֹּא לְצֹרֶךְ, כְּמוֹ יוֹסֵף יְהוֹסֵף (תהלים פא:ו):",1,0],[11,19,"וְהַשּׁוֹעֲרִים. מְמֻנִּין עַל שַׁעֲרֵי הַמִּקְדָּשׁ:",1,0],[11,20,"אִישׁ בְּנַחֲלָתוֹ. כָּל אֶחָד בְּנַחֲלָתוֹ הָיוּ יוֹשְׁבִים׃",1,0],[11,21,"בָּעֹפֶל. מָקוֹם אֶחָד אֲשֶׁר בִּירוּשָׁלַיִם:",1,0],[11,21,"עַל הַנְּתִינִים. מְמֻנִּים עַל הַנְּתִינִים:",2,0],[11,22,"וּפְקִיד הַלְוִיִּם. מְמֻנֶּה עַל הַלְוִיִּם אֲשֶׁר בִּירוּשָׁלִַם:",1,0],[11,22,"לְנֶגֶד מְלֶאכֶת. עַל מְלֶאכֶת הַבַּיִת מְמֻנֶּה, כְּגוֹן בִּנְיָנֵי בֶּדֶק הַבַּיִת וּשְׁאָר דְּבָרִים שֶׁמּוֹצִיאִין מָמוֹן לְמַעֲשֵׂה (לְמַעֲשַׂר) הַבַּיִת, כְּעִנְיָן שֶׁנֶּאֱמַר לְמַעְלָה ״וְשַׁבְּתַי וְיוֹזָבָד עַל הַמְּלָאכָה הַחִיצוֹנָה וְגוֹ׳״ (נחמיה יא:טז)׃",2,0],[11,23,"כִּי מִצְוַת הַמֶּלֶךְ עֲלֵיהֶם. וְהַמֶּלֶךְ הָיָה מַאֲמִין בָּהֶם:",1,0],[11,23,"עַל הַמְשׁוֹרְרִים. לְהוֹצִיא מָמוֹן מֵאוֹצַר הַמֶּלֶךְ דָּרְיָוֶשׁ:",2,0],[11,23,"דְּבַר יוֹם בְּיוֹמוֹ. כְּדֵי לַעֲשׂוֹת צָרְכֵי הַבַּיִת:",3,0],[11,24,"לְיַד הַמֶּלֶךְ. הוּא הָיָה מִצְרָן לַעֲצַת הַמֶּלֶךְ דָּרְיָוֶשׁ:",1,0],[11,24,"לְכָל דָּבָר. לְכָל דִּבְרֵיהֶם אֲשֶׁר לָעָם לְדַבֵּר עֲלֵיהֶם אֶל הַמֶּלֶךְ:",2,0],[11,36,"מַחְלְקוֹת יְהוּדָה לְבִנְיָמִין. הָיוּ מְחַלְּקִין בְּמַחְלְקוֹתָם אָנָה וָאָנָה בְּאֶרֶץ יְהוּדָה וּבִנְיָמִין:",1,0],[12,1,"וְיֵשׁוּעַ. הוּא יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל:",1,0],[12,7,"בִּימֵי יֵשׁוּעַ. שֶׁהָיוּ רָאשִׁים בִּימֵי יְהוֹשֻׁעַ כֹּהֵן גָּדוֹל:",1,0],[12,8,"הֻיְּדוֹת. מִן כְּלֵי שִׁיר, לוֹמַר שִׁירָה:",1,0],[12,9,"לְמִשְׁמָרוֹת. כְּמוֹ שֶׁמָּצִינוּ (דברי הימים א כד:א ואילך) שֶׁהַלְוִיִּם הָיוּ חֲלוּקִים לְעֶשְׂרִים וְאַרְבָּעָה מִשְׁמָרוֹת:",1,0],[12,10,"וְיֵשׁוּעַ הוֹלִיד אֶת יוֹיָקִים וְגוֹ׳. כָּל אֵלּוּ שֶׁבְּמִקְרָא זֶה הָיוּ כֹּהֲנִים גְּדוֹלִים:",1,0],[12,12,"וּבִימֵי יוֹיָקִים. שֶׁהָיָה כֹּהֵן גָּדוֹל הָיוּ כֹהֲנִים הַלָּלוּ, הֵם הָיוּ רָאשִׁים, רָאשֵׁי בֵּית אָב לְמִשְׁמְרוֹתָם:",1,0],[12,12,"לִשְׂרָיָה מְרָיָה. לְמִשְׁמֶרֶת שֶׁל שְׂרָיָה הָיָה מְרָיָה רֹאשׁ בֵּית אָב, וּלְמִשְׁמֶרֶת שֶׁל יִרְמְיָה הָיָה חֲנַנְיָה רֹאשׁ בֵּית אָב, וְכֵן כֻּלָּם. וְאֶת אֲשֶׁר לֹא פֵּרַשׁ כָּל הָעֶשְׂרִים וְאַרְבַּע מִשְׁמָרוֹת, לֹא דִקְדֵּק הַמִּקְרָא בְּכָךְ לִמְנוֹתָם כֻּלָּם:",2,0],[12,22,"הַלְוִיִּם בִּימֵי אֶלְיָשִׁיב. הַלְוִיִּם הַלָּלוּ הָיוּ רָאשֵׁי בֵית אָבוֹת בְּמִשְׁמְרוֹת הַלְוִיִּם בִּימֵי אֶלְיָשִׁיב הַכֹּהֵן הַגָּדוֹל, וְהַכֹּהֲנִים הַמְּנוּיִין לְמַעְלָה בְּסָמוּךְ (פסוקים א-כא) הֵם הָיוּ רָאשֵׁי בֵית אָבוֹת בְּמִשְׁמְרוֹתָם גַּם בִּימֵי אֶלְיָשִׁיב:",1,0],[12,22,"עַל מַלְכוּת. בִּימֵי מַלְכוּת דָּרְיָוֶשׁ הָיָה דָּבָר זֶה:",2,0],[12,23,"וְעַד יְמֵי יוֹחָנָן. כָּל אוֹתָן שֶׁהָיוּ רָאשֵׁי אָבוֹת הַלְוִיִּם עַד יְמֵי יוֹחָנָן כֹּהֵן גָּדוֹל מְנוּיִין שָׁם בְּדִבְרֵי הַיָּמִים:",1,0],[12,24,"מִשְׁמָר לְעֻמַּת מִשְׁמָר. שֶׁהָיוּ חֲלוּקִים בְּמִשְׁמְרוֹתָם לוֹמַר שִׁירָה:",1,0],[12,25,"שׁוֹעֲרִים מִשְׁמָר. שׁוֹעֲרִים הָיוּ בְמִשְׁמָר שֶׁלָּהֶם, לִשְׁמֹר שַׁעֲרֵי הַבַּיִת:",1,0],[12,25,"בָּאֲסוּפֵּי. כְּמוֹ בְּסִפֵּי הַשְּׁעָרִים (דברי הימים א ט:כב):",2,0],[12,26,"אֵלֶּה בִּימֵי יוֹיָקִים. אֵלֶּה הָיוּ שׁוֹעֲרִים בִּימֵי יוֹיָקִים:",1,0],[12,27,"וּבַחֲנֻכַּת חוֹמַת יְרוּשָׁלִָם. בְּתַשְׁלוּם חוֹמַת הָעִיר, לְקַדֵּשׁ אֶת הָעִיר:",1,0],[12,27,"וּבְתוֹדוֹת. וּבְהוֹדָאוֹת:",2,0],[12,28,"וּמִן הַכִּכָּר. אֲשֶׁר סְבִיבוֹת יְרוּשָׁלִַם בָּאוּ הַמְשׁוֹרְרִים:",1,0],[12,30,"וַיִּטַּהֲרוּ. תְּחִלָּה טִהֲרוּ אֶת עַצְמָן, וְאַחַר כָּךְ טִהֲרוּ אֶת אֲחֵרִים:",1,0],[12,30,"וְאֶת הַשְּׁעָרִים וְאֶת הַחוֹמָה. שֶׁלֹּא תִהְיֶה טֻמְאָה שָׁם בָּעִיר:",2,0],[12,31,"מֵעַל לַחוֹמָה. שֶׁקִּדֵּשׁ אֶת הָעִיר, וְהָלְכוּ הַשָּׂרִים וּבֵית דִּין וְהַכֹּהֲנִים וְהַלְוִיִּם עִם שְׁתֵּי תוֹדוֹת סָבִיב לָעִיר. הַכֹּל כַּמְפֹרָשׁ בְּמַסֶּכֶת שְׁבוּעוֹת (שבועות טו,א), כְּדֵי לְקַדֵּשׁ אֶת הָעִיר:",1,0],[12,31,"שְׁתֵּי תוֹדוֹת. שְׁתֵּי לַחְמֵי תוֹדָה, כָּל לֶחֶם וָלֶחֶם קָרוּי תּוֹדָה:",2,0],[12,31,"וְתַהֲלוּכוֹת לַיָּמִין. וְכַאֲשֶׁר יָצְאוּ מִן הָעִיר כְּדֵי לְסוֹבְבָהּ, הָלְכוּ לְצַד יְמִינָהּ:",3,0],[12,34,"יְהוּדָה וּבִנְיָמִין. שְׁנֵי שָׂרִים הָיוּ:",1,0],[12,36,"וְאֶחָיו. חֲבֵירָיו שֶׁל זְכַרְיָה הַכֹּהֵן (נחמיה יב:לה):",1,0],[12,37,"וְעַל שַׁעַר הָעַיִן. לִפְנֵי שַׁעַר הָעַיִן הָלְכוּ סְבִיבוֹת הָעִיר:",1,0],[12,37,"וְנֶגְדָּם עָלוּ. וּלְפָנֵיהֶם עָלוּ מִשַּׁעַר הָעַיִן לְמַעֲלוֹת שֶׁל עִיר דָּוִד וְאוֹתָן מַעֲלוֹת הָיוּ לַחוֹמָה:",2,0],[12,38,"וְהַתּוֹדָה הַשֵּׁנִית הַהוֹלֶכֶת לְמוֹל. תּוֹדָה אַחֶרֶת שֶׁהָיְתָה שֵׁנִית לַחֲבֶרְתָּהּ הָיְתָה הוֹלֶכֶת נֶגֶד חֲבֶרְתָּהּ בְּשָׁוֶה, וְלֹא זוֹ אַחַר זוֹ:",1,0],[12,38,"וַאֲנִי אַחֲרֶיהָ. וַאֲנִי הָיִיתִי הוֹלֵךְ אַחֲרֶיהָ שֶׁל תּוֹדָה:",2,0],[12,39,"וְעָמְדוּ. שָׁם הָיוּ עוֹמְדִים, שֶׁלֹּא לֵילֵךְ יוֹתֵר:",1,0],[12,40,"שְׁתֵּי הַתּוֹדוֹת. שֶׁנָּשְׂאוּ אוֹתָם לְבֵית הַמִּקְדָּשׁ:",1,0],[12,41,"בַּחֲצוֹצְרוֹת. הָיוּ תּוֹקְעִין מִתּוֹךְ שִׂמְחָתָן:",1,0],[12,44,"וַיִּפָּקְדוּ. לְשׁוֹן פְּקִידוּת:",1,0],[12,44,"הַנְּשָׁכוֹת. כְּמוֹ הַלְּשָׁכוֹת שֶׁל בֵּית הַמִּקְדָּשׁ:",2,0],[12,44,"לִכְנוֹס בָּהֶם. וּבְאוֹתָן הַלְּשָׁכוֹת הָיוּ נוֹתְנִים כָּל מַתְּנוֹתֵיהֶם שֶׁל כֹּהֲנִים וּלְוִיִּם, וּמִשָּׁם הָיוּ חוֹלְקִין בֵּינֵיהֶם:",3,0],[12,44,"מְנָאוֹת. כְּמוֹ מָנוֹת (נחמיה ח:י):",4,0],[12,44,"לַכֹּהֲנִים לַלְוִיִּם. כֹּהֲנִים הָיוּ נוֹטְלִים הָרָאוּי לָהֶם וְהַלְוִיִּם הָרָאוּי לָהֶם:",5,0],[12,44,"הָעוֹמְדִים. וּמְשַׁמְּשִׁים שָׁם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּתוֹדוֹת וְהוֹדָאוֹת:",6,0],[12,47,"מְנָיוֹת. כְּמוֹ מָנוֹת (נחמיה ח:י):",1,0],[12,47,"וּמַקְדִּישִׁים לַלְוִיִּם. הָיוּ נוֹתְנִים בְּמַעֲשֵׂר לַלְוִיִּם, וְהֵם הָיוּ נוֹטְלִים מַעֲשֵׂר מִן הַמַּעֲשֵׂר וְנוֹתְנִים לַכֹּהֲנִים:",2,0],[13,3,"כָּל עֵרֶב. כָּל תַּעֲרוֹבוֹת הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, כְּמוֹ ״וְגַם עֵרֶב רַב עָלָה אִתָּם״ (שמות יב:לח):",1,0],[13,4,"וְלִפְנֵי מִזֶּה. וּמִקֹּדֶם לָכֵן:",1,0],[13,4,"קָרוֹב לְטוֹבִיָּה. אוֹתוֹ אֶלְיָשִׁיב הַכֹּהֵן הָיָה קָרוֹב לְטוֹבִיָּה חֲבֵרוֹ שֶׁל סַנְבַלַּט, וְנָתַן שָׁם הַכֹּהֵן כֵּלָיו שֶׁל טוֹבִיָּה:",2,0],[13,5,"וַיַּעַשׂ. אֶלְיָשִׁיב:",1,0],[13,5,"לְפָנִים. שָׁם הָיוּ נוֹתְנִים קֹדֶם שֶׁבָּאתִי לִירוּשָׁלָיִם:",2,0],[13,5,"מִצְוַת הַלְוִיִּם. מַתָּנוֹת הָרְאוּיוֹת לַלְוִיִּם:",3,0],[13,6,"וּבְכָל זֶה. וּבְכָל הַמַּעֲשֶׂה הַזֶּה בָּאתִי אֶל הַמֶּלֶךְ וְחָזַרְתִּי לְבָבֶל:",1,0],[13,6,"נִשְׁאַלְתִּי. שֶׁיִּתֵּן לִי רְשׁוּת לַעֲלוֹת לִירוּשָׁלַיִם וְלַחֲזוֹר:",2,0],[13,9,"וָאֹמְרָה. צִוִּיתִי לְטַהֵר, וַיְטַהֲרוּ הַלְּשָׁכוֹת וְגוֹמֵר:",1,0],[13,10,"מְנָיוֹת. מָנוֹת (נחמיה ח:י):",1,0],[13,10,"לֹא נִתָּנָה. שֶׁלֹּא נָתְנוּ יִשְׂרָאֵל שָׁם הַמַּתָּנוֹת, וְעַל כֵּן בָּרְחוּ וְהָלְכוּ לָהֶם אָנָה וָאָנָה לִשְׁאֹל מַתְּנוֹתֵיהֶם, וְלֹא הָיוּ עוֹסְקִים כָּל כָּךְ בַּעֲבוֹדָתָם:",2,0],[13,11,"וָאֶקְבְּצֵם. קִבַּצְתִּי אֶת הַכֹּהֲנִים וְהַלְוִיִּם לְהַעֲמִידָם עַל מִשְׁמַרְתָּם בַּעֲבוֹדָתָם, וְכָל יִשְׂרָאֵל הָיוּ מְבִיאִים לָהֶם שָׁם מַתְּנוֹתָם:",1,0],[13,13,"כִּי נֶאֱמָנִים. הָיוּ לַחֲלֹק הַמַּתָּנוֹת בֵּינֵיהֶם:",1,0],[13,15,"הָעֲרֵמוֹת. אֲלֻמּוֹת שֶׁל תְּבוּאָה:",1,0],[13,15,"וָאָעִיד. הֵעִידוֹתִי בָּהֶם שֶׁלֹּא לַעֲשׂוֹת:",2,0],[13,15,"בְּיוֹם מִכְרָם צָיִד. בְּיוֹם שֶׁהָיוּ מוֹכְרִים מָזוֹן וְצַיִד, צַיִד כְּמוֹ ״וַיִּתֵּן לָהֶם צֵידָה לַדֶּרֶךְ״ (בראשית מה:כא):",3,0],[13,16,"וְהַצּוֹרִים. סוֹחֲרִים שֶׁל צוֹר מְבִיאִים דָּגִים לִמְכּוֹר:",1,0],[13,19,"וַיְהִי כַּאֲשֶׁר צָלְלוּ. כַּאֲשֶׁר נָטוּ הַצְּלָלִים שֶׁל עֶרֶב שַׁבָּת בַּשְּׁעָרִים (ירמיהו ו:ד), צִוִּיתִי לִסְגֹּר דַּלְתוֹת הָעִיר, שֶׁלֹּא יִפָּתְחוּ עַד אַחַר שַׁבָּת, שֶׁלֹּא יָבוֹאוּ הָרוֹכְלִים בָּעִיר לִמְכֹּר סְחוֹרָתָן, כְּדֵי שֶׁלֹּא יְחַלְּלוּ יִשְׂרָאֵל אֶת הַשַּׁבָּת עַל יְדֵיהֶם:",1,0],[13,20,"וַיָּלִינוּ. וְהָיוּ לָנִים הָרוֹכְלִים וְהַסּוֹחֲרִים בְּיוֹם הַשַּׁבָּת מִחוּץ לִירוּשָׁלַיִם פַּעַם אַחַת וּשְׁתֵּי פְעָמִים, כְּדֵי שֶׁיָּבוֹאוּ בְנֵי יִשְׂרָאֵל לִפְתֹּחַ הַשְּׁעָרִים וְלִקְנוֹת מֵהֶם בַּשַּׁבָּת:",1,0],[13,21,"וָאֹמְרָה אֲלֵיהֶם. הִתְרֵיתִי בְּאוֹתָם הָרוֹכְלִים:",1,0],[13,21,"אִם תִּשְׁנוּ. אִם תּוֹסִיפוּ לַעֲשׂוֹת פַּעַם שְׁנִיָּה:",2,0],[13,21,"מִן הָעֵת. מִן אוֹתוֹ יוֹם וָהָלְאָה לֹא בָאוּ בְּיוֹם הַשַּׁבָּת:",3,0],[13,23,"הוֹשִׁיבוּ נָשִׁים. אֲשֶׁר נָשְׂאוּ לָהֶם נָשִׁים שֶׁל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:",1,0],[13,24,"חֲצִי מְדַבֵּר. הַרְבֵּה מִבְּנֵיהֶם הָיוּ מְדַבְּרִים לְשׁוֹן אַשְׁדּוֹדִית כְּאִמּוֹתָם:",1,0],[13,25,"וָאַכֶּה. נָתַתִּי לָהֶם מַלְקִיּוֹת לְהַלְקוֹתָם כְּדֵי לְהוֹכִיחָם וּלְהַזְכִּירָם:",1,0],[13,26,"גַּם אוֹתוֹ הֶחֱטִיאוּ. כָּל שֶׁכֵּן שֶׁתִּהְיוּ חוֹטְאִים עַל יְדֵי נְשֵׁיכֶם שֶׁל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, וְזֶהוּ שֶׁנֶּאֱמַר בְּסָמוּךְ וְלָכֶם הֲנִשְׁמַע וְגוֹ׳ בִּתְמִיהָּה. כְּלוֹמַר: שְׁלֹמֹה מֶלֶךְ יִשְׂרָאֵל נִמְצָא חָטָא עַל יְדֵי נָשִׁים שֶׁל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, וְאַתֶּם נְשָׂאתֶם נָשִׁים שֶׁל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת לִהְיוֹת חוֹטְאִין:",1,0],[13,28,"וּמִבְּנֵי יוֹיָדָע… חָתָן לְסַנְבַּלַּט. אֶחָד מִבְּנֵי יוֹיָדָע חָתָן לְסַנְבַּלַּט צוֹרֵר הַיְּהוּדִים, וְהִבְרַחְתִּיהוּ מֵעָלָי, לְמַעַן לֹא יִהְיֶה רָגִיל בִּירוּשָׁלַיִם בִּשְׁבִיל חֲתָנוֹ, לִרְאוֹת אֶת הָעִיר וְאֶת מוֹצָאֶיהָ וְאֶת מוֹבָאֶיהָ:",1,0],[13,29,"זָכְרָה לָהֶם. הַטּוֹבָה אֲשֶׁר עָשׂוּ:",1,0],[13,31,"בְּעִתִּים. לְעִתִּים הָיוּ כּוֹרְתִים עֵצִים לַמַּעֲרָכָה:",1,0],[13,31,"וְלַבִּכּוּרִים. שֶׁהָיוּ מְבִיאִים בִּכּוּרִים בְּפֶרֶק אֶחָד, לְכָל דָּבָר וְדָבָר קָבַעְתִּי זְמַנּוֹ:",2,0]]);
